-- Backfill English structure.titleKo subtitles into video_artifacts
-- Generated from apps/english/public/data/*/structure.json
BEGIN;
UPDATE public.video_artifacts SET structure = '{"sections": [{"section": "Personal Hook: Meditation Struggles", "startSegment": 0, "endSegment": 8, "summary": "The speaker opens with a personal anecdote about his early struggles with meditation, describing how difficult it was to simply pay attention to his breath despite the simplicity of the instructions.", "summaryKo": "연사는 명상 초기의 개인적인 어려움에 대한 일화로 시작합니다. 지시 사항이 단순했음에도 호흡에 집중하는 것이 얼마나 어려웠는지 설명합니다.", "keyPoints": ["명상의 지시 사항은 간단했지만 실행은 극도로 어려웠다", "중요한 무언가를 놓치고 있었다는 깨달음"], "titleKo": "명상 초기의 개인적인 어려움에 대한 일화로 시작"}, {"section": "The Science: Reward-Based Learning", "startSegment": 9, "endSegment": 25, "summary": "The speaker explains the evolutionarily conserved reward-based learning process: trigger, behavior, reward. He uses the simple example of food to illustrate how our brains learn through positive and negative reinforcement.", "summaryKo": "연사는 진화적으로 보존된 보상 기반 학습 과정인 자극-행동-보상을 설명합니다. 음식의 간단한 예시를 사용하여 뇌가 긍정적, 부정적 강화를 통해 학습하는 방법을 보여줍니다.", "keyPoints": ["진화적으로 가장 오래 보존된 학습 과정 중 하나", "자극(trigger) - 행동(behavior) - 보상(reward)의 루프", "맥락 의존적 기억의 형성"], "titleKo": "진화적으로 보존된 보상 기반 학습 과정인 자극-…"}, {"section": "How Habits Form: From Food to Smoking", "startSegment": 26, "endSegment": 45, "summary": "The speaker extends the reward-based learning model to explain how emotional eating and smoking develop. The same trigger-behavior-reward loop gets hijacked, going from survival to self-destructive habits.", "summaryKo": "연사는 보상 기반 학습 모델을 확장하여 감정적 폭식과 흡연이 어떻게 발전하는지 설명합니다. 같은 자극-행동-보상 루프가 생존에서 자기 파괴적 습관으로 변질됩니다.", "keyPoints": ["감정적 자극이 배고픔 자극을 대체할 수 있다", "사회적 압력이 흡연 같은 습관을 유발한다", "비만과 흡연은 세계 주요 예방 가능 사망 원인"], "titleKo": "보상 기반 학습 모델을 확장하여 감정적 폭식과…"}, {"section": "The Twist: Curiosity as an Alternative", "startSegment": 46, "endSegment": 65, "summary": "The speaker introduces the key twist: instead of fighting cravings, use curiosity. He describes a mindfulness-based smoking cessation study where participants were told to smoke but be curious about it, leading to a visceral aversion.", "summaryKo": "연사는 핵심적인 변형을 소개합니다: 갈망과 싸우는 대신 호기심을 활용하라는 것입니다. 참가자들에게 담배를 피우되 호기심을 갖도록 한 마음챙김 기반 금연 연구를 설명합니다.", "keyPoints": ["뇌와 싸우는 대신 자연적 학습 과정을 활용", "호기심이 행동 변화의 핵심 도구", "마음챙김하며 흡연했더니 본능적 혐오감을 경험"], "titleKo": "핵심적인 변형을 소개합니다: 갈망과 싸우는 대신…"}, {"section": "Knowledge vs. Wisdom: Disenchantment", "startSegment": 66, "endSegment": 86, "summary": "The speaker distinguishes between knowing something intellectually and knowing it viscerally. He explains the role of the prefrontal cortex in cognitive control and why it fails under stress, making visceral disenchantment more effective.", "summaryKo": "연사는 지적으로 아는 것과 본능적으로 아는 것의 차이를 구분합니다. 인지적 통제에서 전전두엽 피질의 역할과 스트레스 하에서 실패하는 이유를 설명하며, 본능적 환멸이 더 효과적인 이유를 밝힙니다.", "keyPoints": ["지식에서 지혜로의 전환이 행동 변화의 핵심", "전전두엽 피질은 스트레스 시 가장 먼저 작동을 멈춤", "환멸은 더 깊은 수준의 이해를 가능하게 함"], "titleKo": "지적으로 아는 것과 본능적으로 아는 것의 차이를…"}, {"section": "Mindfulness in Practice: Curiosity and Letting Go", "startSegment": 87, "endSegment": 111, "summary": "The speaker explains that mindfulness is about clearly seeing what we get from our behaviors, becoming disenchanted, and naturally letting go. Curiosity is naturally rewarding and breaks cravings into manageable body sensations.", "summaryKo": "연사는 마음챙김이 행동에서 무엇을 얻는지 명확하게 보고, 환멸을 느끼며, 자연스럽게 놓아버리는 것이라고 설명합니다. 호기심은 자연스럽게 보상이 되며 갈망을 관리 가능한 신체 감각으로 분해합니다.", "keyPoints": ["마음챙김은 경험을 명확히 보는 것", "호기심 자체가 자연스러운 보상", "갈망은 관리 가능한 신체 감각의 조합", "두려움 기반 반응 패턴에서 존재로의 전환"], "titleKo": "마음챙김이 행동에서 무엇을 얻는지 명확하게 보고…"}, {"section": "Scientific Evidence and Brain Research", "startSegment": 112, "endSegment": 126, "summary": "The speaker presents research evidence: mindfulness training was twice as effective as standard therapy for smoking cessation. He discusses brain imaging findings about the default mode network and posterior cingulate cortex, and mentions app-based programs.", "summaryKo": "연사는 연구 증거를 제시합니다: 마음챙김 훈련이 금연에서 표준 치료법보다 두 배 효과적이었습니다. 디폴트 모드 네트워크와 후대상피질에 대한 뇌 영상 연구 결과를 논의하고, 앱 기반 프로그램을 언급합니다.", "keyPoints": ["마음챙김 훈련이 표준 치료법 대비 금연 효과 2배", "디폴트 모드 네트워크의 후대상피질이 갈망에 빠질 때 활성화", "놓아버리면 해당 뇌 영역이 조용해짐", "앱과 온라인 기반 프로그램 개발 중"], "titleKo": "연구 증거를 제시합니다: 마음챙김 훈련이 금연에…"}, {"section": "Call to Action: Apply It to Your Life", "startSegment": 127, "endSegment": 143, "summary": "The speaker broadens the application beyond smoking to everyday habits like checking email or texting while driving. He urges the audience to tap into their natural curiosity, notice urges, and feel the joy of letting go.", "summaryKo": "연사는 적용 범위를 흡연 너머 이메일 확인이나 운전 중 문자 같은 일상 습관으로 넓힙니다. 청중에게 자연스러운 호기심을 활용하고, 충동을 알아차리며, 놓아버리는 기쁨을 느끼라고 촉구합니다.", "keyPoints": ["맥락 의존적 기억을 활용한 적시 개입", "일상적 습관에도 같은 원리 적용 가능", "충동 알아차리기 - 호기심 갖기 - 놓아버리는 기쁨 - 반복"], "titleKo": "적용 범위를 흡연 너머 이메일 확인이나 운전 중…"}], "signalExpressions": [{"expression": "When I was first learning to meditate", "type": "hook", "segmentIndex": 1, "role": "개인적 일화로 시작하여 청중의 관심을 끄는 도입부"}, {"expression": "So why is it so hard to pay attention?", "type": "transition", "segmentIndex": 8, "role": "수사적 질문으로 개인 경험에서 과학적 설명으로 전환"}, {"expression": "So what''s going on here?", "type": "transition", "segmentIndex": 11, "role": "청중의 공감을 이끌어낸 후 핵심 설명으로 전환하는 질문"}, {"expression": "It turns out that", "type": "transition", "segmentIndex": 12, "role": "놀라운 사실을 소개하며 본론으로 진입하는 신호"}, {"expression": "And basically goes like this", "type": "transition", "segmentIndex": 16, "role": "복잡한 개념을 단순화하여 설명하겠다는 신호"}, {"expression": "So back to my breath", "type": "transition", "segmentIndex": 45, "role": "도입부의 명상 이야기로 돌아가 해결책 제시로 전환"}, {"expression": "What if instead", "type": "transition", "segmentIndex": 49, "role": "핵심 해결책을 가설 형태로 제안하는 전환점"}, {"expression": "I''ll give you an example", "type": "transition", "segmentIndex": 51, "role": "추상적 개념에서 구체적 사례로 전환"}, {"expression": "In other words", "type": "transition", "segmentIndex": 107, "role": "핵심 메시지를 다른 표현으로 재진술하여 이해를 도움"}, {"expression": "So it actually works", "type": "transition", "segmentIndex": 115, "role": "이론에서 실증적 증거로의 전환을 강조"}, {"expression": "So if you don''t smoke or stress eat", "type": "transition", "segmentIndex": 132, "role": "연구 결과에서 청중의 실생활 적용으로 전환"}, {"expression": "Instead of see text message, compulsively text back, feel a little bit better, notice the urge, get curious, feel the joy of letting go, and repeat.", "type": "conclusion", "segmentIndex": 140, "role": "새로운 습관 루프를 제시하며 강연의 핵심 메시지를 요약"}, {"expression": "Thank you.", "type": "conclusion", "segmentIndex": 143, "role": "강연의 마무리 인사"}]}'::jsonb WHERE language = 'en' AND video_id = '-moW9jvvMr4';
UPDATE public.video_artifacts SET structure = '{"sections": [{"section": "Introduction / Hook", "startSegment": 0, "endSegment": 10, "summary": "Will Stephen opens by declaring he has absolutely nothing to say, but promises that his manner of speaking will make it seem brilliant.", "summaryKo": "윌 스티븐은 할 말이 전혀 없다고 선언하면서 시작하지만, 말하는 방식을 통해 훌륭하게 들리게 만들겠다고 약속합니다.", "keyPoints": ["연사가 아무 내용 없이 시작한다는 역설적 도입", "말하는 방식만으로 똑똑하게 들릴 수 있다는 주제 제시", "청중에게 무언가를 배운 것 같은 느낌이 들 것이라는 예고"], "titleKo": "윌 스티븐은 할 말이 전혀 없다고 선언하면서 시…"}, {"section": "Opening Technique Demonstration", "startSegment": 11, "endSegment": 20, "summary": "He demonstrates common TEDx opening techniques: hand gestures, audience polling, personal anecdotes, and emotional connection—while openly narrating what he''s doing.", "summaryKo": "손동작, 청중 설문, 개인적 일화, 감정적 연결 등 일반적인 TEDx 오프닝 기법을 시연하면서, 자신이 하고 있는 것을 공개적으로 설명합니다.", "keyPoints": ["손동작과 안경 만지기 같은 비언어적 기법 소개", "거수 투표를 통한 청중 참여 유도", "개인적 일화로 긴장을 풀고 호감을 얻는 전략 설명"], "titleKo": "손동작, 청중 설문, 개인적 일화, 감정적 연결…"}, {"section": "Building Authority with Visuals", "startSegment": 21, "endSegment": 42, "summary": "He shows how speakers use images, numbers, and graphs to appear credible—displaying random numbers, meaningless pie charts, and bar graphs to satirize data-driven presentations.", "summaryKo": "이미지, 숫자, 그래프를 사용하여 신뢰감을 주는 방법을 보여줍니다—무작위 숫자, 의미 없는 원형 차트와 막대 그래프를 통해 데이터 기반 프레젠테이션을 풍자합니다.", "keyPoints": ["구글 이미지 검색한 ''과학자'' 사진으로 지적인 느낌 연출", "의미 없는 숫자들로 데이터 제시 방식 패러디", "원형 차트와 막대 그래프로 시각 자료의 설득력 풍자"], "titleKo": "이미지, 숫자, 그래프를 사용하여 신뢰감을 주는…"}, {"section": "Confession and Commitment", "startSegment": 43, "endSegment": 48, "summary": "He confesses he''s a complete phony who is panicking and floundering, but declares he was offered a TED talk and will see it through.", "summaryKo": "자신이 당황하고 허둥대는 완전한 사기꾼이라고 고백하지만, TED 강연 제안을 받았으니 끝까지 하겠다고 선언합니다.", "keyPoints": ["사기꾼이라는 솔직한 고백으로 역설적 진정성 확보", "유튜브 무음 시청 시 전문가처럼 보일 것이라는 관찰", "끝까지 해내겠다는 유머러스한 결의"], "titleKo": "자신이 당황하고 허둥대는 완전한 사기꾼이라고 고…"}, {"section": "Descent into Nonsense", "startSegment": 49, "endSegment": 59, "summary": "He shows stock photos with meaningless words, then descends into complete gibberish, while maintaining the physical mannerisms of a compelling speaker.", "summaryKo": "의미 없는 단어와 사진을 보여주다가 완전한 횡설수설로 내려가면서도, 매력적인 연사의 물리적 매너리즘은 유지합니다.", "keyPoints": ["사진과 단어의 무의미한 조합으로 시각 자료 풍자", "횡설수설하면서도 제스처와 페이싱으로 의미 있어 보이게 하기", "프레임 안경을 쓴 것을 공개하며 외모 조작 폭로"], "titleKo": "의미 없는 단어와 사진을 보여주다가 완전한 횡설…"}, {"section": "Climax and Conclusion", "startSegment": 60, "endSegment": 70, "summary": "He slows down and builds to a mock-emotional conclusion, pointing out that both the beginning and end of his talk contain nothing—and that''s the entire point.", "summaryKo": "속도를 늦추고 가짜 감동적 결론을 향해 나아가며, 강연의 처음과 끝 모두 아무것도 없다는 것이 바로 요점이라고 지적합니다.", "keyPoints": ["톤 변화와 속도 조절로 감동적인 순간 연출", "처음과 끝 모두 아무것도 없었다는 메타적 결론", "청중에게 생각하라거나 안 해도 된다는 유머러스한 마무리"], "titleKo": "속도를 늦추고 가짜 감동적 결론을 향해 나아가며…"}], "signalExpressions": [{"expression": "Hear that?", "type": "hook", "segmentIndex": 1, "role": "청중의 주의를 환기하는 오프닝 질문으로, 호기심을 유발합니다."}, {"expression": "And yet", "type": "transition", "segmentIndex": 8, "role": "앞의 내용(아무것도 없음)에서 반전(그럼에도 똑똑하게 들리게 하겠다)으로 전환합니다."}, {"expression": "Now, I''m going to get started with", "type": "transition", "segmentIndex": 11, "role": "도입부에서 본격적인 시연으로 넘어가는 전환 표현입니다."}, {"expression": "By show of hands", "type": "hook", "segmentIndex": 14, "role": "청중 참여를 유도하는 고전적인 프레젠테이션 기법입니다."}, {"expression": "And now, I''m going to bring it to a broader point", "type": "transition", "segmentIndex": 20, "role": "개인적인 이야기에서 더 넓은 주제로 전환하는 신호 표현입니다."}, {"expression": "Now, if you don''t believe me, let''s take a look at the numbers", "type": "transition", "segmentIndex": 27, "role": "주장에서 증거 제시로 전환하며 신뢰성을 구축하는 표현입니다."}, {"expression": "And to follow that up", "type": "transition", "segmentIndex": 39, "role": "숫자 데이터에서 그래프 시각 자료로 넘어가는 연결 표현입니다."}, {"expression": "But you know what?", "type": "transition", "segmentIndex": 47, "role": "고백에서 결의로 전환하는 구어적 전환 표현입니다."}, {"expression": "And now I''m going to slow things down a little bit", "type": "transition", "segmentIndex": 60, "role": "페이스를 바꾸며 결론부로 진입하는 전환 신호입니다."}, {"expression": "If there''s one thing you take away from my talk", "type": "conclusion", "segmentIndex": 64, "role": "핵심 메시지를 요약하며 결론으로 향하는 고전적인 마무리 표현입니다."}, {"expression": "Think about that. Or don''t, that''s fine.", "type": "conclusion", "segmentIndex": 67, "role": "유머러스한 반전으로 전통적인 TED 마무리를 패러디합니다."}, {"expression": "And now I''m going to stop talking.", "type": "conclusion", "segmentIndex": 68, "role": "강연의 끝을 직접적으로 알리는 솔직한 마무리 표현입니다."}]}'::jsonb WHERE language = 'en' AND video_id = '8S0FDjFBj8o';
UPDATE public.video_artifacts SET structure = '{"sections": [{"section": "Hook / Opening Question", "startSegment": 0, "endSegment": 7, "summary": "Speaker hooks the audience with a compelling ''what if'' question about something that can immediately and lastingly benefit the brain, including protection from depression, Alzheimer''s, and dementia.", "summaryKo": "화자가 ''만약에...''라는 강렬한 질문으로 청중의 관심을 끌며, 뇌에 즉각적이고 지속적인 이점을 줄 수 있는 무언가를 소개합니다. 우울증, 알츠하이머, 치매로부터 보호하는 것을 포함합니다.", "keyPoints": ["뇌에 즉각적이고 긍정적인 효과를 주는 것이 있다", "장기적으로 뇌를 보호할 수 있다", "우울증, 알츠하이머, 치매 예방에 도움"], "titleKo": "도입: 강렬한 질문으로 관심 유도"}, {"section": "Thesis Statement / Topic Reveal", "startSegment": 8, "endSegment": 16, "summary": "Reveals the answer: physical activity. Exercise has immediate, long-lasting, and protective benefits for the brain. Speaker frames her personal neuroscience journey as the narrative vehicle.", "summaryKo": "답을 밝힙니다: 바로 신체 활동입니다. 운동은 뇌에 즉각적이고 오래 지속되며 보호적인 효과가 있습니다. 화자는 자신의 신경과학 여정을 이야기의 틀로 설정합니다.", "keyPoints": ["신체 활동(운동)이 핵심 주제", "뇌에 즉각적이고 지속적이며 보호적인 효과", "신경과학 교수로서의 자기 실험"], "titleKo": "답을 밝힙니다: 바로 신체 활동"}, {"section": "Brain Anatomy Background", "startSegment": 17, "endSegment": 30, "summary": "Provides essential neuroscience background by introducing two key brain areas: the prefrontal cortex (decision-making, focus, personality) and the hippocampus (long-term memory formation), using a real preserved brain.", "summaryKo": "실제 보존된 뇌를 사용하여 두 가지 핵심 뇌 영역을 소개합니다: 전전두엽 피질(의사결정, 집중, 성격)과 해마(장기 기억 형성).", "keyPoints": ["전전두엽 피질: 의사결정, 집중, 주의력, 성격", "해마: 장기 기억 형성과 유지의 핵심 구조", "측두엽 깊숙한 곳에 위치"], "titleKo": "실제 보존된 뇌를 사용하여 두 가지 핵심 뇌 영…"}, {"section": "Original Research on Memory", "startSegment": 31, "endSegment": 42, "summary": "Describes her original research passion: understanding how brief moments create lifelong memories by recording electrical activity of individual neurons in the hippocampus.", "summaryKo": "원래의 연구 열정을 설명합니다: 해마의 개별 뉴런 전기 활동을 기록하여 짧은 순간이 어떻게 평생의 기억을 만드는지 이해하려 했습니다.", "keyPoints": ["짧은 순간이 어떻게 평생의 기억이 되는지 의문", "해마의 개별 뇌세포 활동 기록", "뉴런 간 전기 신호 해독 시도"], "titleKo": "원래의 연구 열정을 설명합니다: 해마의 개별 뉴…"}, {"section": "Personal Turning Point", "startSegment": 43, "endSegment": 69, "summary": "Shares her personal story of being overweight, socially isolated, and miserable despite career success. A humbling river rafting trip motivated her to start exercising, leading to mood and energy boosts.", "summaryKo": "커리어 성공에도 불구하고 과체중이고 사회적으로 고립되어 비참했던 개인적 이야기를 공유합니다. 래프팅 여행이 운동을 시작하게 만들었고, 기분과 에너지가 향상되었습니다.", "keyPoints": ["연구 몰두로 사회생활 없이 체중 11kg 증가", "래프팅 여행에서 가장 약한 사람이었던 경험", "다양한 운동 시작 후 기분과 에너지 향상"], "titleKo": "커리어 성공에도 불구하고 과체중이고 사회적으로…"}, {"section": "Discovery: Exercise Improves Cognition", "startSegment": 70, "endSegment": 99, "summary": "After 1.5 years of regular exercise, she noticed improved focus and memory during grant writing. Research literature confirmed her personal experience, leading her to shift her entire research focus to exercise and the brain.", "summaryKo": "1년 반의 규칙적 운동 후, 연구비 신청서 작성 시 집중력과 기억력이 향상되었음을 발견합니다. 연구 문헌이 개인 경험을 확인해 주었고, 연구 방향을 완전히 전환합니다.", "keyPoints": ["1년 반 운동 후 집중력과 기억력 향상 발견", "연구비 신청서 작성이 잘 되는 것에서 변화 인식", "문헌 검토로 운동-뇌 효과 확인, 연구 방향 전환"], "titleKo": "1년 반의 규칙적 운동 후, 연구비 신청서 작성…"}, {"section": "Three Key Benefits of Exercise", "startSegment": 100, "endSegment": 151, "summary": "Presents her research conclusion with three reasons exercise is transformative: (1) immediate effects on neurotransmitters, mood, focus, and reaction time; (2) long-lasting structural brain changes including new hippocampal cells; (3) protective effects against neurodegenerative diseases.", "summaryKo": "운동이 혁신적인 세 가지 이유를 제시합니다: (1) 신경전달물질, 기분, 집중력, 반응 시간에 대한 즉각적 효과; (2) 해마 신생 세포를 포함한 장기적 뇌 구조 변화; (3) 신경퇴행성 질환에 대한 보호 효과.", "keyPoints": ["즉각 효과: 도파민·세로토닌·노르아드레날린 증가, 기분·집중·반응 시간 향상", "장기 효과: 새로운 뇌세포 생성, 해마 부피 증가, 주의력 향상", "보호 효과: 신경퇴행성 질환과 노화에 의한 인지 저하 지연", "뇌를 위한 ''슈퍼차지된 퇴직연금''이라는 비유"], "titleKo": "운동이 혁신적인 세 가지 이유를 제시합니다: (…"}, {"section": "Practical Exercise Recommendations", "startSegment": 153, "endSegment": 167, "summary": "Addresses the audience''s practical question about minimum exercise needed. Recommends 3-4 times per week, 30 minutes minimum, aerobic exercise. Offers accessible alternatives like power walking, taking stairs, and power vacuuming.", "summaryKo": "필요한 최소 운동량에 대한 청중의 실용적 질문에 답합니다. 주 3-4회, 최소 30분, 유산소 운동을 권장합니다. 파워 워킹, 계단 이용, 힘차게 청소기 돌리기 등 접근 가능한 대안을 제시합니다.", "keyPoints": ["철인 3종 경기 선수가 될 필요 없음", "주 3-4회, 최소 30분 운동", "유산소 운동으로 심박수 올리기", "파워 워킹, 계단 이용, 청소 등 일상 활동도 효과적"], "titleKo": "필요한 최소 운동량에 대한 청중의 실용적 질문에…"}, {"section": "Current Research Goals", "startSegment": 168, "endSegment": 178, "summary": "Describes her current research mission: to go beyond the basic rule of thumb and find the optimum exercise prescription personalized for age, fitness level, and genetic background.", "summaryKo": "현재 연구 목표를 설명합니다: 기본 원칙을 넘어 나이, 체력 수준, 유전적 배경에 맞는 개인 맞춤형 최적 운동 처방을 찾는 것입니다.", "keyPoints": ["기억 연구의 선구자에서 운동 탐험가로 변신", "기본 원칙을 넘어선 최적 운동 처방 연구", "나이, 체력, 유전 배경에 맞는 맞춤형 접근"], "titleKo": "현재 연구 목표를 설명합니다: 기본 원칙을 넘어…"}, {"section": "Interactive Exercise Demo", "startSegment": 179, "endSegment": 197, "summary": "Transitions from talking about exercise to actually doing it. As a certified exercise instructor, she leads the audience in a one-minute call-and-response workout with affirmations.", "summaryKo": "운동에 대해 이야기하는 것에서 실제로 하는 것으로 전환합니다. 공인 운동 강사로서 청중과 함께 1분간 콜 앤 리스폰스 운동을 진행합니다.", "keyPoints": ["말하는 것과 행동하는 것의 차이를 실천으로 보여줌", "1분간 콜 앤 리스폰스 운동", "''나는 강하다'', ''나는 영감이 넘친다'', ''나는 불타오른다'' 등 긍정 확언"], "titleKo": "운동에 대해 이야기하는 것에서 실제로 하는 것으…"}, {"section": "Closing / Call to Action", "startSegment": 198, "endSegment": 203, "summary": "Concludes with a powerful call to action: exercise will give you a happier, more productive life today, protect your brain from incurable diseases, and change the trajectory of your life for the better.", "summaryKo": "강력한 행동 촉구로 마무리합니다: 운동은 오늘 더 행복하고 생산적인 삶을 주고, 불치병으로부터 뇌를 보호하며, 인생 궤적을 더 나은 방향으로 바꿔줄 것입니다.", "keyPoints": ["운동이 더 행복하고 생산적인 삶을 가져다줌", "불치병으로부터 뇌 보호", "인생의 궤적을 더 나은 방향으로 변화"], "titleKo": "강력한 행동 촉구로 마무리합니다: 운동은 오늘…"}], "signalExpressions": [{"expression": "What if I told you...", "type": "hook", "segmentIndex": 0, "role": "청중의 호기심을 유발하는 도입 질문으로, 강연의 핵심 주장을 가정적 질문 형태로 제시"}, {"expression": "I am talking about...", "type": "topic_reveal", "segmentIndex": 8, "role": "도입부의 서스펜스를 해소하며 핵심 주제(신체 활동)를 직접적으로 밝히는 표현"}, {"expression": "So what I want to do today is tell you a story", "type": "roadmap", "segmentIndex": 12, "role": "강연의 구조를 미리 알려주는 로드맵 표현으로, 개인적 이야기를 통해 전개할 것임을 예고"}, {"expression": "So here is a real preserved human brain", "type": "visual_cue", "segmentIndex": 21, "role": "시각적 보조 자료를 소개하며 청중의 주의를 집중시키는 전환 표현"}, {"expression": "But a few years ago, I did something very unusual in science.", "type": "narrative_turn", "segmentIndex": 42, "role": "이야기의 전환점을 알리며, 연구 방향 전환이라는 극적 변화를 예고"}, {"expression": "And that''s when I put it together.", "type": "revelation", "segmentIndex": 87, "role": "깨달음의 순간을 알리는 표현으로, 개인 경험과 과학적 발견을 연결하는 전환점"}, {"expression": "For the following three reasons.", "type": "enumeration", "segmentIndex": 104, "role": "핵심 논증을 세 가지로 구조화하여 청중이 따라가기 쉽게 만드는 열거 신호"}, {"expression": "Number one...", "type": "enumeration", "segmentIndex": 105, "role": "첫 번째 핵심 논점(즉각 효과)을 시작하는 순서 표지"}, {"expression": "Number two...", "type": "enumeration", "segmentIndex": 128, "role": "두 번째 핵심 논점(장기 효과)을 시작하는 순서 표지"}, {"expression": "And finally...", "type": "enumeration", "segmentIndex": 134, "role": "세 번째이자 마지막 핵심 논점(기분 지속 효과)을 시작하는 순서 표지"}, {"expression": "But really, the most transformative thing...", "type": "emphasis", "segmentIndex": 137, "role": "가장 중요한 논점(보호 효과)으로 전환하며 강조하는 표현"}, {"expression": "So this is the point in the talk where everybody says...", "type": "audience_engagement", "segmentIndex": 153, "role": "청중의 생각을 대변하며 실용적 조언 섹션으로 자연스럽게 전환"}, {"expression": "But it''s one thing to talk about exercise, and it''s another to do it.", "type": "transition", "segmentIndex": 179, "role": "이론에서 실천으로 전환하며 인터랙티브 운동 섹션을 도입하는 대조 표현"}, {"expression": "I want to leave you with one last thought", "type": "closing", "segmentIndex": 198, "role": "강연의 마무리를 알리고 핵심 메시지를 전달하기 위한 결론 신호"}]}'::jsonb WHERE language = 'en' AND video_id = 'BHY0FxzoKZE';
UPDATE public.video_artifacts SET structure = '{"sections": [{"section": "Introduction: America as a Global Superpower", "startSegment": 0, "endSegment": 2, "summary": "Introduces the United States as the most powerful country in history, with vast military reach and global influence, and sets up the historical question of how it got there.", "summaryKo": "미국을 역사상 가장 강력한 국가로 소개하며, 광대한 군사적 영향력과 글로벌 영향력을 가지고 있다고 설명하고, 어떻게 그렇게 되었는지에 대한 역사적 질문을 제기합니다.", "keyPoints": ["미국은 800개 이상의 군사 기지와 전 세계 군사비의 37%를 보유", "전례 없는 번영과 낮은 분쟁 수준을 이끈 글로벌 시스템의 리더", "이 위치를 이해하려면 건국 시절로 돌아가야 함"], "titleKo": "미국을 역사상 가장 강력한 국가로 소개하며, 광…"}, {"section": "Early Expansion and the Debate Over Imperialism", "startSegment": 3, "endSegment": 9, "summary": "Covers the first 70 years of U.S. history, the westward expansion across North America, and the fierce debate between expansionists and anti-imperialists over whether America should become a global power.", "summaryKo": "미국 역사의 첫 70년, 북미 대륙의 서쪽 확장, 그리고 미국이 세계 강국이 되어야 하는지에 대한 팽창주의자와 반제국주의자 간의 치열한 논쟁을 다룹니다.", "keyPoints": ["미국의 초기 영토 확장과 원주민 학살", "태평양과 대서양 너머 확장에 대한 분열된 의견", "수어드의 알래스카 매입 성공과 의회의 견제"], "titleKo": "미국 역사의 첫 70년, 북미 대륙의 서쪽 확장…"}, {"section": "The Industrial Revolution and the Spanish-American War", "startSegment": 10, "endSegment": 19, "summary": "Explains how the Industrial Revolution centralized power in the federal government, enabling President McKinley to push the U.S. into war with Spain in 1898, and the subsequent rapid acquisition of overseas territories.", "summaryKo": "산업혁명이 어떻게 연방 정부에 권력을 집중시켰는지, 매킨리 대통령이 1898년 스페인과의 전쟁으로 미국을 이끈 과정, 그리고 이후 해외 영토의 급속한 획득을 설명합니다.", "keyPoints": ["산업혁명으로 인한 연방 정부 권력 집중", "1898년 미서전쟁과 푸에르토리코, 괌, 필리핀 획득", "하와이, 파나마 운하 지대 등 추가 영토 확보"], "titleKo": "산업혁명이 어떻게 연방 정부에 권력을 집중시켰는…"}, {"section": "World War I and the Rise of Isolationism", "startSegment": 20, "endSegment": 26, "summary": "Describes how WWI demonstrated America''s growing influence, Wilson''s ambitious but ultimately failed League of Nations, and the continued strength of isolationist sentiment.", "summaryKo": "제1차 세계대전이 미국의 성장하는 영향력을 어떻게 보여주었는지, 윌슨의 야심 찬 그러나 결국 실패한 국제연맹, 그리고 고립주의 정서의 지속적인 힘을 설명합니다.", "keyPoints": ["미국의 참전이 전쟁 종결에 결정적 역할", "윌슨 대통령의 국제연맹 구상", "의회의 국제연맹 가입 거부와 고립주의의 지속"], "titleKo": "제1차 세계대전이 미국의 성장하는 영향력을 어떻…"}, {"section": "World War II and the New Global Order", "startSegment": 27, "endSegment": 41, "summary": "Traces the path from America''s unavoidable entry into WWII through Pearl Harbor, to its emergence as the dominant post-war power, creating the UN, the Bretton Woods system, and other global institutions.", "summaryKo": "진주만 공격을 통한 미국의 불가피한 제2차 세계대전 참전부터, 유엔, 브레턴우즈 체제 및 기타 글로벌 기관을 창설한 전후 지배적 강대국으로의 부상까지를 추적합니다.", "keyPoints": ["진주만 공격으로 미국의 제2차 세계대전 참전", "미국이 유일하게 경제적 파탄을 피하고 핵무기를 보유", "유엔과 브레턴우즈 체제(세계은행, IMF) 창설"], "titleKo": "진주만 공격을 통한 미국의 불가피한 제2차 세계…"}, {"section": "The Cold War and Containment", "startSegment": 42, "endSegment": 55, "summary": "Explains the ideological clash between the U.S. and Soviet Union, the creation of NATO, the containment strategy, and how the Cold War pulled America into alliances and interventions worldwide.", "summaryKo": "미국과 소련 간의 이념적 충돌, 나토 창설, 봉쇄 전략, 그리고 냉전이 어떻게 미국을 전 세계의 동맹과 개입으로 끌어들였는지를 설명합니다.", "keyPoints": ["미소 이념 대립과 냉전의 시작", "나토 창설과 봉쇄 전략 채택", "사우디아라비아, 이스라엘, 한국과의 동맹", "이란, 아프가니스탄, 니카라과 등에 대한 비밀 개입"], "titleKo": "미국과 소련 간의 이념적 충돌, 나토 창설, 봉…"}, {"section": "Post-Cold War: Maintaining the System", "startSegment": 56, "endSegment": 63, "summary": "Describes how, after the Cold War ended, the U.S. chose to maintain its global system of alliances and institutions rather than withdraw, with bipartisan consensus supporting active global management.", "summaryKo": "냉전 종식 후 미국이 철수하지 않고 글로벌 동맹과 제도 시스템을 유지하기로 선택한 과정과, 적극적인 세계 관리를 지지하는 초당적 합의를 설명합니다.", "keyPoints": ["냉전 후에도 군사 인프라와 동맹 유지", "부시와 클린턴 대통령의 적극적 세계 관리 결정", "나토의 존속과 확장"], "titleKo": "냉전 종식 후 미국이 철수하지 않고 글로벌 동맹…"}, {"section": "Conclusion: Trump and the Challenge to Consensus", "startSegment": 64, "endSegment": 73, "summary": "Introduces Donald Trump as a potential disruption to decades of foreign policy consensus, questioning American alliances, NATO, and the WTO, representing a return toward isolationism.", "summaryKo": "도널드 트럼프를 수십 년간의 외교 정책 합의에 대한 잠재적 위협으로 소개하며, 미국의 동맹, 나토, 세계무역기구에 의문을 제기하고 고립주의로의 회귀를 나타냅니다.", "keyPoints": ["트럼프의 동맹국 보호 비용 분담 주장", "나토와 세계무역기구에 대한 의문 제기", "1945년 이래 외교 정책 합의로부터의 급격한 이탈"], "titleKo": "도널드 트럼프를 수십 년간의 외교 정책 합의에…"}], "signalExpressions": [{"expression": "The modern United States is the most powerful country in human history", "type": "hook", "segmentIndex": 0, "role": "강력한 사실 제시로 시청자의 관심을 즉시 끌어들이는 도입부"}, {"expression": "To understand America''s position in the world... you have to go back", "type": "transition", "segmentIndex": 2, "role": "현재에서 과거로의 시간적 전환을 안내하며 역사적 서술의 시작을 알림"}, {"expression": "But something was happening in the late 1800s that would change the debate", "type": "transition", "segmentIndex": 10, "role": "새로운 역사적 전환점을 소개하며 산업혁명 시대로의 전환을 예고"}, {"expression": "The key turning point came in 1898", "type": "transition", "segmentIndex": 13, "role": "결정적 역사적 순간을 명시적으로 표시하여 서술의 핵심 사건을 강조"}, {"expression": "World War I showed just how much America''s influence had grown", "type": "transition", "segmentIndex": 20, "role": "제1차 세계대전으로의 시대 전환을 알리며 미국 영향력의 성장을 요약"}, {"expression": "World War II would transform America''s global presence forever", "type": "transition", "segmentIndex": 30, "role": "제2차 세계대전의 역사적 중요성을 강조하며 영구적 변화를 예고"}, {"expression": "The most famous example of this is", "type": "transition", "segmentIndex": 33, "role": "추상적 개념에서 구체적 사례(유엔)로 전환하는 신호"}, {"expression": "Their goal? To establish a global financial system", "type": "hook", "segmentIndex": 39, "role": "수사적 질문을 사용하여 긴장감을 조성하고 브레턴우즈 협정을 소개"}, {"expression": "The issue, though, is that", "type": "transition", "segmentIndex": 42, "role": "문제점이나 갈등을 도입하여 냉전으로의 서술 전환을 알림"}, {"expression": "After the Berlin Wall fell", "type": "transition", "segmentIndex": 56, "role": "냉전 종식이라는 주요 역사적 사건을 기점으로 새로운 시대로 전환"}, {"expression": "Except, perhaps, for Donald Trump", "type": "transition", "segmentIndex": 64, "role": "짧고 극적인 문장으로 합의에 대한 예외를 도입하며 결론부로 전환"}, {"expression": "This is a sharp divergence from the consensus", "type": "conclusion", "segmentIndex": 70, "role": "영상의 핵심 주장을 요약하며 현재 상황의 역사적 의미를 강조"}, {"expression": "We''ll find out soon enough", "type": "conclusion", "segmentIndex": 72, "role": "열린 결말로 마무리하며 시청자에게 미래에 대한 사색을 유도"}]}'::jsonb WHERE language = 'en' AND video_id = 'BShvYeyMm_Y';
UPDATE public.video_artifacts SET structure = '{"sections": [{"section": "Introduction", "startSegment": 0, "endSegment": 5, "summary": "Adam introduces the lesson topic: 3 tips for sounding like a native English speaker. He sets expectations that improvement requires time and lots of practice.", "summaryKo": "Adam이 수업 주제를 소개합니다: 원어민처럼 들리기 위한 3가지 팁. 향상에는 시간과 많은 연습이 필요하다고 기대치를 설정합니다.", "keyPoints": ["원어민처럼 들리려면 많은 연습이 필요합니다", "영어권 나라에 사는 것이 가장 좋은 방법입니다", "인내심을 갖고 연습하세요"], "titleKo": "Adam이 수업 주제를 소개합니다: 원어민처럼…"}, {"section": "Tip 1: Connecting Words - Same Consonants", "startSegment": 6, "endSegment": 16, "summary": "The first tip covers connecting words when one ends with a consonant and the next begins with the same consonant. The first consonant is dropped (e.g., ''black coffee''). This also applies to T and D which are formed similarly in the mouth.", "summaryKo": "첫 번째 팁은 같은 자음으로 끝나고 시작하는 단어 연결을 다룹니다. 첫 번째 자음을 생략합니다 (예: ''black coffee''). 입에서 비슷하게 형성되는 T와 D에도 적용됩니다.", "keyPoints": ["같은 자음이 만나면 첫 번째를 생략합니다", "''black coffee''에서 K는 하나만 발음합니다", "T와 D도 같은 원리가 적용됩니다"], "titleKo": "첫 번째 팁은 같은 자음으로 끝나고 시작하는 단…"}, {"section": "Tip 1: Connecting Words - Consonant to Vowel", "startSegment": 17, "endSegment": 27, "summary": "Continuing the connecting words tip: when a word ends in a consonant and the next begins with a vowel, roll the consonant into the vowel. Key example: ''not at all'' becomes ''na-ta-tal''. Also covers reductions like ''What do you do?''", "summaryKo": "단어 연결 팁 계속: 자음으로 끝나는 단어 다음에 모음으로 시작하는 단어가 오면 자음을 모음으로 굴려 넣습니다. 핵심 예시: ''not at all''이 ''na-ta-tal''이 됩니다. ''What do you do?'' 같은 축약도 다룹니다.", "keyPoints": ["자음 다음에 모음이 오면 연결하세요", "''not at all''이 자연스럽게 연결되는 예시", "''What do you do?''의 축약 발음"], "titleKo": "단어 연결 팁 계속: 자음으로 끝나는 단어 다음…"}, {"section": "Application to Listening Tests", "startSegment": 28, "endSegment": 32, "summary": "Adam explains how connected speech knowledge helps with listening sections of English tests like IELTS, TOEFL, TOEIC, and CELPIP. Test recordings use natural connected speech that students need to decode.", "summaryKo": "Adam이 연결 발화 지식이 IELTS, TOEFL, TOEIC, CELPIP 같은 영어 시험의 듣기 영역에 어떻게 도움이 되는지 설명합니다. 시험 녹음은 학생들이 해독해야 하는 자연스러운 연결 발화를 사용합니다.", "keyPoints": ["듣기 시험에서 연결 발화를 이해해야 합니다", "녹음에서 개별 단어를 구분하는 것이 시험의 일부입니다", "말하기와 듣기 연습을 모두 하세요"], "titleKo": "Adam이 연결 발화 지식이 IELTS, TOE…"}, {"section": "Tip 2: Squeezing Words (Syllable Reduction)", "startSegment": 33, "endSegment": 45, "summary": "The second tip covers syllable reduction in common words. ''Comfortable'' drops the ''or'' (4 to 3 syllables), ''interesting'' drops a syllable (4 to 3), and ''every'' drops the middle E (3 to 2). The concept of enunciation vs. natural speech is introduced.", "summaryKo": "두 번째 팁은 일반적인 단어에서의 음절 축소를 다룹니다. ''Comfortable''은 ''or''을 생략하고(4에서 3음절), ''interesting''은 음절을 생략하고(4에서 3), ''every''는 가운데 E를 생략합니다(3에서 2). 또렷한 발음 vs 자연스러운 발화 개념을 소개합니다.", "keyPoints": ["''comfortable''은 3음절로 발음합니다", "''interesting''은 3음절로 줄어듭니다", "''every''는 2음절로 발음합니다", "강조할 때만 모든 음절을 또렷하게 발음합니다"], "titleKo": "두 번째 팁은 일반적인 단어에서의 음절 축소를…"}, {"section": "Tip 3: Squeezing Letters (Sound Changes)", "startSegment": 46, "endSegment": 56, "summary": "The third tip covers how letter combinations change sounds in natural speech: TR sounds like CHR (tree, country, treat), DR sounds like JR (hundred), and D+Y becomes J (did you). These are habits that require practice.", "summaryKo": "세 번째 팁은 자연스러운 발화에서 글자 조합이 소리를 어떻게 바꾸는지 다룹니다: TR은 CHR처럼(tree, country, treat), DR은 JR처럼(hundred), D+Y는 J가 됩니다(did you). 이것들은 연습이 필요한 습관입니다.", "keyPoints": ["TR은 CHR처럼 발음됩니다", "DR은 JR처럼 발음됩니다", "D+Y는 J 소리가 됩니다", "원어민은 이것을 무의식적으로 합니다"], "titleKo": "세 번째 팁은 자연스러운 발화에서 글자 조합이…"}, {"section": "Practice Advice and Conclusion", "startSegment": 57, "endSegment": 65, "summary": "Adam recommends listening practice through TV sitcoms, radio, and websites like TED.com. He suggests dictation exercises to identify individual words in connected speech. He closes by directing viewers to engvid.com for more pronunciation lessons.", "summaryKo": "Adam이 TV 시트콤, 라디오, TED.com 같은 웹사이트를 통한 듣기 연습을 추천합니다. 연결 발화에서 개별 단어를 식별하는 받아쓰기 연습을 제안합니다. engvid.com의 추가 발음 수업을 안내하며 마무리합니다.", "keyPoints": ["TV 시트콤과 라디오를 들으세요", "TED.com에서 원어민을 들을 수 있습니다", "받아쓰기 연습을 해보세요", "engvid.com에서 더 많은 발음 수업을 찾을 수 있습니다"], "titleKo": "Adam이 TV 시트콤, 라디오, TED"}], "signalExpressions": [{"expression": "Hi again. Welcome back to www.engvid.com.", "type": "hook", "segmentIndex": 0, "role": "인사와 채널 소개로 시청자의 관심을 끄는 도입부"}, {"expression": "Today, I''m going to help you sound a little bit more like a native speaker", "type": "hook", "segmentIndex": 0, "role": "수업의 목표와 기대 효과를 명확하게 제시하는 도입"}, {"expression": "Well, before I say anything, let me just tell you", "type": "transition", "segmentIndex": 2, "role": "본론에 들어가기 전 중요한 전제 조건을 먼저 언급하는 전환"}, {"expression": "So we''re looking at pronunciation", "type": "transition", "segmentIndex": 5, "role": "주제를 명시적으로 선언하며 본론으로 전환"}, {"expression": "We''re going to start with connecting words", "type": "transition", "segmentIndex": 8, "role": "첫 번째 팁을 소개하며 구체적 내용으로 전환"}, {"expression": "Now, another thing is when a word ends in a consonant", "type": "transition", "segmentIndex": 22, "role": "''Now''와 ''another thing''으로 새로운 하위 주제로 전환"}, {"expression": "For those of you who are going to be taking a test", "type": "transition", "segmentIndex": 28, "role": "특정 청중을 대상으로 한 실용적 응용 섹션으로 전환"}, {"expression": "Another thing we do is we squeeze some words", "type": "transition", "segmentIndex": 33, "role": "두 번째 주요 팁(단어 압축)으로의 전환"}, {"expression": "Another word like that. Interesting.", "type": "transition", "segmentIndex": 38, "role": "같은 범주의 다른 예시로 전환"}, {"expression": "Last. Squeeze letters.", "type": "transition", "segmentIndex": 46, "role": "세 번째이자 마지막 팁으로의 전환을 ''Last''로 명시"}, {"expression": "But also, make sure you do a lot of listening", "type": "transition", "segmentIndex": 57, "role": "팁에서 연습 조언 섹션으로 전환"}, {"expression": "Thank you for joining me today", "type": "conclusion", "segmentIndex": 64, "role": "감사 인사로 수업을 마무리하는 결론부"}, {"expression": "Please go to the YouTube channel, my channel on YouTube, subscribe", "type": "conclusion", "segmentIndex": 64, "role": "구독 유도와 작별 인사로 영상을 마무리"}]}'::jsonb WHERE language = 'en' AND video_id = 'ChZJ1Q3GSuI';
UPDATE public.video_artifacts SET structure = '{"sections": [{"section": "Personal Story: IQ Isn''t Everything", "startSegment": 0, "endSegment": 9, "summary": "Opening: Personal story about teaching 7th grade math and discovering IQ isn''t everything", "keyPoints": ["교사로서의 경험을 통해 IQ가 성적의 유일한 요인이 아님을 발견", "성적 우수자가 반드시 IQ가 높지 않았고, IQ가 높아도 성적이 낮은 학생 존재"], "signalExpressions": ["When I was 27 years old", "What struck me was that"], "titleKo": "개인 경험"}, {"section": "From Classroom to Graduate School", "startSegment": 10, "endSegment": 22, "summary": "Transition: From classroom observation to graduate school — reframing the question from IQ to motivation", "keyPoints": ["7학년 수학은 어렵지만 불가능하지 않음 — 노력의 문제", "교육에는 동기 부여/심리학적 관점의 이해가 필요", "핵심 질문: ''학습 속도 이상의 것이 성공을 결정한다면?''"], "signalExpressions": ["And that got me thinking", "I came to the conclusion that", "But what if"], "titleKo": "핵심 내용"}, {"section": "Research Across Extreme Environments", "startSegment": 23, "endSegment": 38, "summary": "Research journey: Studies across West Point, Spelling Bee, schools, and companies — all pointing to one factor", "keyPoints": ["다양한 극한 환경에서 성공 예측 인자 연구", "웨스트포인트, 철자 맞히기 대회, 초임 교사, 영업사원 대상", "사회적 지능, 외모, 건강, IQ 모두 아닌 하나의 특성 발견"], "signalExpressions": ["I started studying", "My research team and I", "In all those very different contexts"], "titleKo": "연구 결과"}, {"section": "Defining Grit: Passion and Perseverance", "startSegment": 39, "endSegment": 54, "summary": "Core concept: Defining grit and presenting evidence from Chicago public schools", "keyPoints": ["그릿 = 장기 목표에 대한 열정 + 인내", "마라톤 비유: 인생은 단거리가 아닌 마라톤", "시카고 연구: 그릿 높은 학생이 졸업률 유의미하게 높음", "가정 소득, 시험 점수 등 변수 통제 후에도 유효"], "signalExpressions": ["It was grit", "Grit is", "Turns out that"], "titleKo": "핵심 내용"}, {"section": "The Gap: How to Build Grit", "startSegment": 55, "endSegment": 75, "summary": "The gap: We know little about building grit — growth mindset as the best lead so far", "keyPoints": ["그릿을 키우는 방법에 대한 과학적 지식 부족 고백", "재능 ≠ 그릿 (오히려 반비례)", "캐럴 드웩의 성장 마인드셋이 현재 최선의 아이디어", "뇌가 변화할 수 있다는 믿음이 실패 후 끈기를 높임"], "signalExpressions": ["The most shocking thing", "The honest answer is", "So far, the best idea"], "titleKo": "핵심 내용"}, {"section": "Call to Action: Be Gritty About Building Grit", "startSegment": 76, "endSegment": 88, "summary": "Call to action: We need to be gritty about making kids grittier", "keyPoints": ["성장 마인드셋만으로는 부족, 더 많은 연구 필요", "최고의 아이디어를 검증하고, 실패를 감수해야 함", "재귀적 메시지: 그릿을 키우려면 우리 자신이 끈기를 가져야 함"], "signalExpressions": ["But we need more", "That''s where I''m going to end my remarks", "In other words"], "titleKo": "결론 및 행동 촉구"}], "signalExpressions": [{"expression": "When I was 27 years old", "type": "narrative_opening", "segmentIndex": 0, "role": "개인 경험으로 시작하여 청중의 관심을 끄는 서사적 도입"}, {"expression": "What struck me was that", "type": "emphasis", "segmentIndex": 6, "role": "핵심 관찰을 강조하는 강조 구문"}, {"expression": "And that got me thinking", "type": "transition", "segmentIndex": 10, "role": "관찰에서 탐구로의 전환을 알리는 연결 표현"}, {"expression": "But what if", "type": "rhetorical_question", "segmentIndex": 21, "role": "기존 가정에 도전하는 수사적 질문으로 주제 전환"}, {"expression": "In all those very different contexts", "type": "summary", "segmentIndex": 36, "role": "다양한 연구를 종합하며 공통점을 도출하는 요약 표현"}, {"expression": "It was grit", "type": "reveal", "segmentIndex": 39, "role": "배제법 후 핵심 답을 공개하는 극적 전환점"}, {"expression": "Turns out that", "type": "evidence", "segmentIndex": 49, "role": "연구 결과를 구어체로 자연스럽게 보고하는 학술 표현"}, {"expression": "The honest answer is", "type": "honesty", "segmentIndex": 61, "role": "한계를 솔직히 인정하여 신뢰를 구축하는 고백 표현"}, {"expression": "So far, the best idea I''ve heard", "type": "recommendation", "segmentIndex": 67, "role": "겸손한 추천으로 성장 마인드셋 소개"}, {"expression": "In other words", "type": "restatement", "segmentIndex": 83, "role": "핵심 메시지를 한 문장으로 재정리하며 강연 마무리"}]}'::jsonb WHERE language = 'en' AND video_id = 'H14bBuluwB8';
UPDATE public.video_artifacts SET structure = '{"sections": [{"section": "Computing''s Exponential Growth Hits Physical Limits", "startSegment": 0, "endSegment": 5, "summary": "The narrator introduces the history of computing and how exponential growth in processing power is now hitting physical limits as components approach atomic scale.", "summaryKo": "컴퓨팅의 역사를 소개하고, 처리 능력의 기하급수적 성장이 부품이 원자 크기에 접근하면서 물리적 한계에 부딪히고 있다고 설명해.", "keyPoints": ["Computer power has grown exponentially since the 1960s", "Parts are approaching the size of an atom", "This creates a fundamental problem for further progress"], "titleKo": "컴퓨팅의 역사를 소개하고, 처리 능력의 기하급수…"}, {"section": "How Traditional Computers Work", "startSegment": 6, "endSegment": 16, "summary": "Explains the basic building blocks of traditional computers: transistors, logic gates, and modules. Uses the analogy of seven-year-olds doing simple math to show how simple operations combine into complex computing.", "summaryKo": "기존 컴퓨터의 기본 구성 요소인 트랜지스터, 논리 게이트, 모듈을 설명해. 간단한 수학을 하는 7살짜리 아이들에 비유해서 단순한 연산이 어떻게 복잡한 컴퓨팅이 되는지 보여줘.", "keyPoints": ["Computers consist of transistors, logic gates, and modules", "Transistors are simple on/off switches processing bits", "Complex calculations emerge from combining simple operations"], "titleKo": "기존 컴퓨터의 기본 구성 요소인 트랜지스터, 논…"}, {"section": "The Quantum Problem: Tunneling at Atomic Scale", "startSegment": 17, "endSegment": 24, "summary": "Explains why miniaturization causes problems at the quantum level. Quantum tunneling allows electrons to bypass barriers, breaking traditional computing. Scientists respond by developing quantum computers.", "summaryKo": "소형화가 양자 수준에서 왜 문제를 일으키는지 설명해. 양자 터널링으로 전자가 장벽을 통과할 수 있어서 기존 컴퓨팅이 작동하지 않게 돼. 과학자들은 양자 컴퓨터를 개발해 대응하고 있어.", "keyPoints": ["At atomic scale, quantum tunneling lets electrons pass through barriers", "Traditional computers stop working reliably at this scale", "Scientists aim to harness quantum properties for quantum computers"], "titleKo": "소형화가 양자 수준에서 왜 문제를 일으키는지 설…"}, {"section": "Qubits and Superposition", "startSegment": 25, "endSegment": 37, "summary": "Introduces qubits and the concept of superposition. Unlike classical bits, qubits can exist in multiple states simultaneously, allowing exponential growth in parallel computation.", "summaryKo": "큐비트와 중첩의 개념을 소개해. 고전적 비트와 달리 큐비트는 여러 상태에 동시에 존재할 수 있어서 병렬 계산이 기하급수적으로 증가할 수 있어.", "keyPoints": ["Qubits can be in superposition of both 0 and 1 simultaneously", "Measurement collapses the superposition to a definite state", "20 qubits can store a million values in parallel"], "titleKo": "큐비트와 중첩의 개념을 소개해"}, {"section": "Entanglement and Quantum Gates", "startSegment": 38, "endSegment": 47, "summary": "Covers entanglement, quantum gates, and how quantum computing works in practice. Entangled qubits react to each other instantaneously, and quantum gates manipulate superpositions to perform massive parallel calculations.", "summaryKo": "얽힘, 양자 게이트, 양자 컴퓨팅의 실제 작동 방식을 다뤄. 얽힌 큐비트는 서로 즉각적으로 반응하고, 양자 게이트는 중첩을 조작해서 대규모 병렬 계산을 수행해.", "keyPoints": ["Entanglement links qubits so measuring one reveals the other''s state", "Quantum gates manipulate superpositions and probabilities", "Superposition and entanglement enable exponentially more efficient computation"], "titleKo": "얽힘, 양자 게이트, 양자 컴퓨팅의 실제 작동…"}, {"section": "Applications: Databases, Encryption, and Drug Discovery", "startSegment": 48, "endSegment": 61, "summary": "Presents practical applications of quantum computers: database searching with Grover''s algorithm, breaking encryption systems, and simulating quantum physics for drug discovery and materials science.", "summaryKo": "양자 컴퓨터의 실용적 응용 분야를 소개해: 그로버 알고리즘을 이용한 데이터베이스 검색, 암호화 시스템 해독, 신약 개발과 재료 과학을 위한 양자 물리학 시뮬레이션.", "keyPoints": ["Database searching becomes vastly faster with quantum algorithms", "Public-key encryption could be broken by quantum speed-up", "Quantum simulations could revolutionize medicine through protein modeling"], "titleKo": "양자 컴퓨터의 실용적 응용 분야를 소개해: 그로…"}, {"section": "The Uncertain but Exciting Future", "startSegment": 62, "endSegment": 64, "summary": "The narrator concludes by acknowledging that the future of quantum computing is uncertain — it may be a specialized tool or a transformative revolution — and emphasizes the spirit of exploration.", "summaryKo": "양자 컴퓨팅의 미래가 불확실하다는 점을 인정하며 마무리해. 전문적인 도구가 될 수도 있고 혁명이 될 수도 있으며, 탐구 정신을 강조해.", "keyPoints": ["The ultimate impact of quantum computers remains unknown", "They could be specialized tools or a revolution for humanity", "The only way to find out is to keep pushing forward"], "titleKo": "양자 컴퓨팅의 미래가 불확실하다는 점을 인정하며…"}], "signalExpressions": [{"expression": "For most of our history", "type": "transition", "segmentIndex": 0, "role": "역사적 맥락을 설정하며 이야기를 시작해요"}, {"expression": "But this process is about to meet its physical limits", "type": "emphasis", "segmentIndex": 3, "role": "핵심 문제를 예고하며 긴박감을 조성해요"}, {"expression": "To understand why this is a problem, we have to clear up some basics", "type": "transition", "segmentIndex": 5, "role": "기본 개념 설명으로 전환하며 청중을 안내해요"}, {"expression": "However, with parts getting tinier and tinier", "type": "transition", "segmentIndex": 17, "role": "양자 문제로의 전환을 알리는 역접 표현이에요"}, {"expression": "In a nutshell", "type": "summary", "segmentIndex": 18, "role": "복잡한 개념을 간결하게 요약하겠다는 신호예요"}, {"expression": "To solve this problem, scientists are trying to", "type": "transition", "segmentIndex": 24, "role": "문제에서 해결책으로 전환하며 양자 컴퓨터를 소개해요"}, {"expression": "This is called superposition", "type": "emphasis", "segmentIndex": 30, "role": "핵심 용어를 정의하며 개념을 명확하게 해요"}, {"expression": "Superposition is a game-changer", "type": "emphasis", "segmentIndex": 33, "role": "중첩의 중요성을 강조하며 실질적 의미를 설명하기 시작해요"}, {"expression": "What this means is that", "type": "summary", "segmentIndex": 45, "role": "복잡한 설명을 실질적인 의미로 바꿔 설명해요"}, {"expression": "So while quantum computers will probably not replace our home computers", "type": "transition", "segmentIndex": 48, "role": "이론에서 실제 응용 분야로 전환하며 기대를 조정해요"}, {"expression": "Another really exciting new use is", "type": "transition", "segmentIndex": 57, "role": "새로운 응용 분야로 자연스럽게 전환해요"}, {"expression": "We have no idea where the limits of technology are", "type": "summary", "segmentIndex": 64, "role": "전체 영상을 마무리하며 열린 결론으로 끝내요"}]}'::jsonb WHERE language = 'en' AND video_id = 'JhHMJCUmq28';
UPDATE public.video_artifacts SET structure = '{"sections": [{"section": "Introduction & Hook", "startSegment": 0, "endSegment": 4, "summary": "Dr. Lara Boyd introduces herself as a brain researcher at the University of British Columbia and poses the central questions: How do we learn, and why do some of us learn things more easily than others?", "summaryKo": "로라 보이드 박사가 브리티시 컬럼비아 대학교의 뇌 연구자로 자신을 소개하고, 핵심 질문을 던집니다: 우리는 어떻게 배우는가, 왜 어떤 사람들은 더 쉽게 배우는가?", "keyPoints": ["학습의 근본적 질문 제기", "연사의 전문성 소개"], "titleKo": "로라 보이드 박사가 브리티시 컬럼비아 대학교의…"}, {"section": "Brain Research & Misconceptions", "startSegment": 5, "endSegment": 22, "summary": "Boyd describes brain research as an exciting frontier and debunks common misconceptions: that the brain cannot change after childhood, and that parts of the brain are silent when not in use. She credits advances like MRI for these discoveries.", "summaryKo": "보이드는 뇌 연구를 흥미로운 최전선으로 설명하고 흔한 오해를 깨뜨립니다: 어린 시절 이후 뇌가 변할 수 없다는 것, 사용하지 않는 뇌 부분은 비활성이라는 것. MRI 같은 기술 발전 덕분에 이런 발견이 가능했습니다.", "keyPoints": ["뇌에 대한 일반적인 오해 반박", "MRI 기술의 중요성", "뇌는 쉬고 있을 때도 활발히 활동함"], "titleKo": "보이드는 뇌 연구를 흥미로운 최전선으로 설명하고…"}, {"section": "Neuroplasticity Introduction", "startSegment": 23, "endSegment": 34, "summary": "Introduces the concept of neuroplasticity — the brain''s ability to change whenever we learn. She explains that this was only discovered about 25 years ago, overturning the belief that brain changes after puberty were only negative.", "summaryKo": "신경가소성 개념을 소개합니다 — 배울 때마다 뇌가 변하는 능력. 25년 전에야 발견되었으며, 사춘기 이후 뇌 변화는 부정적이기만 하다는 믿음을 뒤집었습니다.", "keyPoints": ["신경가소성의 정의", "25년 전까지의 잘못된 믿음", "나이와 관계없이 뇌는 변화함", "뇌 재조직화가 손상 회복을 돕는다"], "titleKo": "신경가소성 개념을 소개합니다 — 배울 때마다 뇌…"}, {"section": "Three Ways the Brain Changes", "startSegment": 35, "endSegment": 84, "summary": "Details three mechanisms of neuroplastic change: (1) Chemical changes that support short-term memory, (2) Structural changes that support long-term memory and involve physical rewiring of connections, and (3) Functional changes where brain regions become more excitable with use. Includes examples like Braille readers, dominant hand motor regions, and London taxi drivers.", "summaryKo": "신경가소적 변화의 세 가지 메커니즘을 상세히 설명합니다: (1) 단기 기억을 지원하는 화학적 변화, (2) 장기 기억을 지원하고 물리적 재배선을 수반하는 구조적 변화, (3) 사용할수록 뇌 영역이 더 흥분하기 쉬워지는 기능적 변화. 점자 읽는 사람, 우세한 손의 운동 영역, 런던 택시 운전사 등의 예가 포함됩니다.", "keyPoints": ["화학적 변화 = 단기 기억", "구조적 변화 = 장기 기억", "기능적 변화 = 뇌 영역 활성화", "피아노/저글링 연습 예시", "점자, 런던 택시 운전사 예시"], "titleKo": "신경가소적 변화의 세 가지 메커니즘을 상세히 설…"}, {"section": "Limits of Neuroplasticity & Stroke Research", "startSegment": 85, "endSegment": 103, "summary": "Poses the question of why we can''t learn everything easily despite neuroplasticity. Transitions to her specific research on stroke recovery, noting that stroke is the leading cause of long-term disability and that effective rehabilitation has been elusive.", "summaryKo": "신경가소성에도 불구하고 왜 모든 것을 쉽게 배울 수 없는지 질문합니다. 뇌졸중 회복에 대한 자신의 구체적 연구로 전환하며, 뇌졸중이 장기 장애의 주요 원인이고 효과적인 재활이 어려웠다고 지적합니다.", "keyPoints": ["신경가소성의 한계에 대한 질문", "뇌졸중 = 성인 장기 장애의 주요 원인", "효과적 재활 중재법 개발 실패", "사회적 문제로서의 뇌졸중"], "titleKo": "신경가소성에도 불구하고 왜 모든 것을 쉽게 배울…"}, {"section": "Behavior as the Driver of Change", "startSegment": 104, "endSegment": 131, "summary": "Argues that behavior and practice are the best drivers of neuroplastic change. Discusses her research on brain stimulation, exercise, and robotics. Emphasizes that neuroplasticity works both ways — positive (learning new skills) and negative (addiction, chronic pain, forgetting).", "summaryKo": "행동과 연습이 신경가소적 변화의 최고의 동력이라고 주장합니다. 뇌 자극, 운동, 로봇공학에 대한 연구를 논의합니다. 신경가소성이 양방향으로 작동함을 강조합니다 — 긍정적(새 기술 학습)이고 부정적(중독, 만성 통증, 망각)일 수 있습니다.", "keyPoints": ["행동이 뇌 변화의 핵심 동력", "더 어려운 연습 = 더 많은 학습", "신경가소성의 양면성", "하지 않는 행동도 뇌를 형성함"], "titleKo": "행동과 연습이 신경가소적 변화의 최고의 동력이라…"}, {"section": "Personalized Learning & Medicine", "startSegment": 132, "endSegment": 156, "summary": "Introduces the concept that there is no one-size-fits-all approach to learning. Discusses personalized medicine from cancer treatment and applies it to stroke recovery using biomarkers. Extends this to personalized learning for everyone.", "summaryKo": "학습에 만능 접근법은 없다는 개념을 소개합니다. 암 치료의 개인 맞춤 의학을 논의하고 바이오마커를 사용하여 뇌졸중 회복에 적용합니다. 이를 모든 사람을 위한 개인 맞춤 학습으로 확장합니다.", "keyPoints": ["1만 시간의 법칙에 대한 반론", "개인 맞춤 의학의 개념", "바이오마커를 통한 치료법 매칭", "개인 맞춤 학습의 필요성"], "titleKo": "학습에 만능 접근법은 없다는 개념을 소개"}, {"section": "Conclusion & Call to Action", "startSegment": 157, "endSegment": 179, "summary": "Concludes by telling the audience their brains have already changed during the talk. Calls on them to study how they learn best, practice healthy brain behaviors, and go out to ''build the brain you want.''", "summaryKo": "강연 중에 청중의 뇌가 이미 변했다고 말하며 마무리합니다. 자신이 어떻게 가장 잘 배우는지 연구하고, 건강한 뇌 행동을 연습하며, ''원하는 뇌를 만들어라''고 촉구합니다.", "keyPoints": ["강연 중 뇌가 이미 변했음", "각자 다르게 변화함", "건강한 행동 반복 촉구", "''원하는 뇌를 만드세요''라는 메시지"], "titleKo": "강연 중에 청중의 뇌가 이미 변했다고 말하며 마…"}], "signalExpressions": [{"expression": "So how do we learn?", "type": "hook", "segmentIndex": 1, "role": "청중의 호기심을 자극하는 핵심 질문으로 강연을 시작하는 도입부 훅"}, {"expression": "As I mentioned, I''m Dr. Laura Boyd.", "type": "introduction", "segmentIndex": 2, "role": "연사의 신원과 자격을 확립하는 자기 소개"}, {"expression": "For example, we used to think that after childhood...", "type": "example", "segmentIndex": 14, "role": "추상적 개념을 구체적 예시로 설명하기 위한 전환"}, {"expression": "And perhaps the most exciting, the most interesting and transformative", "type": "emphasis", "segmentIndex": 23, "role": "핵심 발견(신경가소성)을 소개하기 전 청중의 기대를 높이는 강조 표현"}, {"expression": "So what does it look like?", "type": "transition", "segmentIndex": 35, "role": "개념적 설명에서 구체적 메커니즘으로 전환하는 질문"}, {"expression": "And the first is chemical.", "type": "enumeration", "segmentIndex": 36, "role": "세 가지 메커니즘 중 첫 번째를 나열하는 구조적 표지"}, {"expression": "The second way that the brain can change...", "type": "enumeration", "segmentIndex": 42, "role": "세 가지 중 두 번째 메커니즘으로의 전환"}, {"expression": "And let me give you an example of how.", "type": "example", "segmentIndex": 48, "role": "이론적 설명을 일상적 경험과 연결하는 예시 도입"}, {"expression": "Now, the last way that your brain can change...", "type": "enumeration", "segmentIndex": 73, "role": "세 가지 중 마지막 메커니즘으로의 전환"}, {"expression": "So I''ve just told you really how awesomely neuroplastic your brain is.", "type": "summary", "segmentIndex": 85, "role": "이전 섹션을 요약하고 새로운 방향의 질문으로 전환"}, {"expression": "And so this is what I study.", "type": "transition", "segmentIndex": 91, "role": "일반적 논의에서 개인 연구로 전환하는 표현"}, {"expression": "One thing is absolutely clear.", "type": "emphasis", "segmentIndex": 104, "role": "핵심 주장을 강조하기 위한 강력한 전환 표현"}, {"expression": "The second lesson we''ve learned about the brain...", "type": "enumeration", "segmentIndex": 132, "role": "두 번째 주요 교훈으로의 전환"}, {"expression": "So when you leave this room today...", "type": "conclusion", "segmentIndex": 157, "role": "결론부를 시작하며 강연 내용을 청중의 경험에 연결"}, {"expression": "Go out and build the brain you want.", "type": "call-to-action", "segmentIndex": 177, "role": "청중에게 행동을 촉구하는 강력한 마무리 메시지"}]}'::jsonb WHERE language = 'en' AND video_id = 'LNHBMFCzznE';
UPDATE public.video_artifacts SET structure = '{"sections": [{"section": "intro", "startSegment": 0, "endSegment": 4, "summary": "The narrator introduces the legendary origin of tea through the myth of Shen Nong, the divine Chinese farmer who accidentally discovered tea after being poisoned.", "summaryKo": "신농씨의 신화를 통해 차의 전설적인 기원을 소개해요. 독에 중독된 후 우연히 차를 발견한 이야기로 청중의 흥미를 끌어요.", "keyPoints": ["Shen Nong, the divine farmer, was poisoned 72 times", "A tea leaf accidentally revived him", "This is an ancient legend, not historical fact"], "titleKo": "신농씨의 신화를 통해 차의 전설적인 기원을 소개"}, {"section": "body", "startSegment": 5, "endSegment": 11, "summary": "The narrator transitions from legend to archaeological evidence, explaining that tea was cultivated in China 6,000 years ago and was originally consumed as food, not as a drink.", "summaryKo": "전설에서 고고학적 증거로 전환하며, 차가 6,000년 전 중국에서 재배되었고 원래는 음료가 아닌 음식으로 소비되었다고 설명해요.", "keyPoints": ["Tea cultivation dates back 6,000 years in China", "This predates the Great Pyramids by 1,500 years", "Tea was originally eaten as a vegetable or with porridge"], "titleKo": "전설에서 고고학적 증거로 전환하며, 차가 6,0…"}, {"section": "body", "startSegment": 12, "endSegment": 21, "summary": "Tea shifted from food to drink 1,500 years ago. The preparation evolved into matcha, and a rich Chinese tea culture emerged with tea becoming a subject of art, poetry, and imperial favor.", "summaryKo": "1,500년 전에 차가 음식에서 음료로 바뀌었어요. 준비 방법이 말차로 발전했고, 차가 예술과 시, 황제의 총애의 대상이 되면서 풍부한 중국 차 문화가 형성되었어요.", "keyPoints": ["Heat and moisture unlocked complex flavors from tea leaves", "Matcha became the standard preparation method", "Tea culture included art, poetry, and foam art similar to modern latte art"], "titleKo": "1,500년 전에 차가 음식에서 음료로 바뀌었어…"}, {"section": "body", "startSegment": 22, "endSegment": 31, "summary": "Tea spread to Japan in the 9th century, leading to the Japanese tea ceremony. During the Ming Dynasty, loose leaf tea replaced cakes. China maintained a tea monopoly, and Dutch traders brought tea to Europe in the 1600s.", "summaryKo": "9세기에 차가 일본에 전해져 다도가 탄생했어요. 명나라 때 잎차가 떡차를 대체했고, 중국은 차 독점권을 유지했으며, 1600년대에 네덜란드 상인들이 차를 유럽에 가져왔어요.", "keyPoints": ["A Japanese monk brought tea to Japan during the Tang Dynasty", "The Ming Dynasty shifted from cake tea to loose leaf tea", "China held a monopoly on tea alongside porcelain and silk", "Dutch traders brought tea to Europe in large quantities"], "titleKo": "9세기에 차가 일본에 전해져 다도가 탄생했어요"}, {"section": "body", "startSegment": 32, "endSegment": 41, "summary": "Tea became enormously popular in Europe, particularly England. Its high price and Chinese monopoly fueled intense competition, giving rise to Clipper Ships and a massive global trade.", "summaryKo": "차가 유럽, 특히 영국에서 엄청난 인기를 끌었어요. 높은 가격과 중국의 독점이 치열한 경쟁을 부추겨 클리퍼선이 탄생하고 거대한 글로벌 무역이 형성되었어요.", "keyPoints": ["Queen Catherine of Braganza popularized tea in English aristocracy", "Britain''s colonial expansion spread tea culture globally", "Tea sold for 10 times the price of coffee in 1700", "Clipper Ships were built to race tea to Europe"], "titleKo": "차가 유럽, 특히 영국에서 엄청난 인기를 끌었어…"}, {"section": "body", "startSegment": 42, "endSegment": 51, "summary": "Britain''s tea trade led to the devastating Opium Wars with China. Britain traded opium for tea, triggering addiction and conflict. The defeated Qing Dynasty ceded Hong Kong, weakening China for over a century.", "summaryKo": "영국의 차 무역은 중국과의 파괴적인 아편 전쟁으로 이어졌어요. 영국이 차 대신 아편을 교역하면서 중독과 분쟁이 발생했고, 패배한 청나라는 홍콩을 할양하며 1세기 이상 약화되었어요.", "keyPoints": ["Britain traded opium for Chinese tea when silver became too expensive", "Opium caused a public health crisis in China", "The first Opium War (1839-1842) resulted in China ceding Hong Kong", "The war weakened China''s global standing for over a century"], "titleKo": "영국의 차 무역은 중국과의 파괴적인 아편 전쟁으…"}, {"section": "body", "startSegment": 52, "endSegment": 56, "summary": "The British East India Company sent Robert Fortune on a covert mission to steal tea plants and expertise from China. He smuggled them to Darjeeling, India, breaking China''s monopoly and driving tea''s global spread.", "summaryKo": "영국 동인도 회사가 로버트 포춘을 비밀 작전에 보내 중국에서 차나무와 기술을 훔쳐왔어요. 인도 다르질링으로 밀반출하며 중국의 독점을 깨고 차의 세계적 확산을 이끌었어요.", "keyPoints": ["Robert Fortune disguised himself and infiltrated China''s tea regions", "He smuggled tea plants and workers to Darjeeling, India", "This broke China''s monopoly and made tea an everyday commodity worldwide"], "titleKo": "영국 동인도 회사가 로버트 포춘을 비밀 작전에…"}, {"section": "conclusion", "startSegment": 57, "endSegment": 61, "summary": "Today tea is the world''s second most consumed beverage after water, with an incredible diversity of preparation methods across cultures worldwide.", "summaryKo": "오늘날 차는 물 다음으로 세계에서 두 번째로 많이 소비되는 음료이며, 전 세계 문화마다 놀라울 정도로 다양한 준비 방법이 있어요.", "keyPoints": ["Tea is the second most consumed beverage in the world", "Preparation styles range from sugary Turkish tea to salty Tibetan butter tea", "There are nearly as many tea traditions as there are cultures"], "titleKo": "오늘날 차는 물 다음으로 세계에서 두 번째로 많…"}], "signalExpressions": [{"expression": "During a long day spent roaming the forest", "type": "emphasis", "segmentIndex": 0, "role": "서사적 묘사로 시작하여 이야기 속으로 청중을 끌어들이는 도입부예요"}, {"expression": "And that is how we discovered tea", "type": "summary", "segmentIndex": 4, "role": "전설의 핵심을 요약하며 이야기의 첫 번째 단락을 마무리해요"}, {"expression": "Or so an ancient legend goes, at least", "type": "transition", "segmentIndex": 4, "role": "전설에서 사실적 서술로 전환하며, 이야기의 신뢰성에 대한 여지를 남겨요"}, {"expression": "Archaeological evidence suggests", "type": "transition", "segmentIndex": 7, "role": "신화에서 과학적 증거로 전환하며 역사적 서술을 시작해요"}, {"expression": "Tea only shifted from food to drink 1,500 years ago", "type": "transition", "segmentIndex": 12, "role": "차의 용도 변화라는 중요한 전환점을 알리며 새로운 시대로 넘어가요"}, {"expression": "In the 9th century, during the Tang Dynasty", "type": "transition", "segmentIndex": 22, "role": "구체적인 시대와 왕조를 제시하며 일본으로의 차 전파 이야기를 시작해요"}, {"expression": "That spread began in earnest around the early 1600s", "type": "transition", "segmentIndex": 30, "role": "차의 세계적 확산이 본격화된 시점을 알리며 유럽 진출 이야기로 전환해요"}, {"expression": "At first, Britain paid for all this Chinese tea with silver", "type": "transition", "segmentIndex": 42, "role": "무역 방식의 변화를 소개하며 아편 전쟁으로 이어지는 서술을 시작해요"}, {"expression": "This act triggered the first opium war", "type": "emphasis", "segmentIndex": 47, "role": "인과관계를 명확히 하며 전쟁이라는 중대한 사건의 시작을 강조해요"}, {"expression": "The British East India Company also wanted", "type": "transition", "segmentIndex": 52, "role": "''also''를 통해 추가적인 영국의 행동을 소개하며 로버트 포춘의 이야기로 전환해요"}, {"expression": "Today, tea is the second most consumed beverage", "type": "transition", "segmentIndex": 57, "role": "과거 서술에서 현재로 돌아오며 결론부로 전환해요"}]}'::jsonb WHERE language = 'en' AND video_id = 'LaLvVc1sS20';
UPDATE public.video_artifacts SET structure = '{"sections": [{"title": "Introduction: Personal Background", "titleKo": "도입: 개인 배경 이야기", "startSegment": 0, "endSegment": 9, "summary": "Luis Von Ahn introduces himself as being from Guatemala, using humor to describe his country''s relationship with Mexico and the US. He sets up the theme of poverty and inequality.", "summaryKo": "루이스 폰 안이 과테말라 출신이라고 소개하며, 과테말라와 멕시코 및 미국의 관계를 유머러스하게 설명해요. 가난과 불평등이라는 주제를 설정해요."}, {"title": "Education and Inequality", "titleKo": "교육과 불평등", "startSegment": 10, "endSegment": 22, "summary": "Luis argues that education often reinforces inequality rather than solving it. He shares his personal story of receiving a good education thanks to his mother''s sacrifices, eventually earning a Ph.D. in computer science.", "summaryKo": "루이스는 교육이 불평등을 해소하기보다 오히려 강화한다고 주장해요. 어머니의 희생 덕분에 좋은 교육을 받고 컴퓨터 과학 박사 학위를 받은 개인적인 이야기를 나눠요."}, {"title": "Why Foreign Languages?", "titleKo": "왜 외국어인가?", "startSegment": 23, "endSegment": 55, "summary": "Luis explains why Duolingo chose to start with foreign languages rather than math or computer science. The key reason: learning English directly increases income potential, unlike other subjects that require multiple steps.", "summaryKo": "루이스는 듀오링고가 수학이나 컴퓨터 과학 대신 외국어로 시작한 이유를 설명해요. 핵심 이유는 영어 학습이 다른 과목과 달리 소득 잠재력을 직접적으로 높이기 때문이에요."}, {"title": "Mobile-First and Freemium Model", "titleKo": "모바일 우선과 프리미엄 모델", "startSegment": 56, "endSegment": 84, "summary": "Luis describes Duolingo''s decision to use smartphones as the delivery platform and the freemium business model. Rich subscribers in wealthy countries effectively pay for free education for users in poorer countries.", "summaryKo": "루이스는 스마트폰을 교육 전달 플랫폼으로 사용하기로 한 결정과 프리미엄 비즈니스 모델을 설명해요. 부유한 나라의 유료 구독자가 가난한 나라 사용자의 무료 교육비를 효과적으로 부담해요."}, {"title": "Competing with Addictive Apps", "titleKo": "중독적인 앱과의 경쟁", "startSegment": 85, "endSegment": 101, "summary": "The central challenge: smartphones come with highly addictive apps like TikTok and Instagram. Duolingo''s solution is to make the ''broccoli taste like dessert'' by using the same psychological techniques these apps employ.", "summaryKo": "핵심 과제: 스마트폰에는 틱톡이나 인스타그램 같은 중독적인 앱이 있어요. 듀오링고의 해결책은 같은 심리적 기법을 사용해서 ''브로콜리를 디저트 맛이 나게'' 만드는 거예요."}, {"title": "Technique 1: Streaks", "titleKo": "기법 1: 스트릭", "startSegment": 102, "endSegment": 121, "summary": "Luis explains how streaks -- counting consecutive days of use -- motivate daily engagement. Over 3 million Duolingo users have streaks longer than 365 days. Japan has the longest average streaks.", "summaryKo": "루이스는 연속 사용 일수를 세는 스트릭이 어떻게 매일 참여하게 하는지 설명해요. 300만 명 이상의 듀오링고 사용자가 365일 이상의 스트릭을 가지고 있고, 일본이 평균 스트릭이 가장 길어요."}, {"title": "Technique 2: Notifications", "titleKo": "기법 2: 알림", "startSegment": 122, "endSegment": 163, "summary": "Luis discusses Duolingo''s notification strategy: AI-driven timing (best time = 24 hours after last use), stopping after 7 days of inactivity, and the surprisingly effective passive-aggressive farewell notification. The owl mascot has become a meme.", "summaryKo": "루이스는 듀오링고의 알림 전략을 설명해요: AI 기반 타이밍(최적 시간 = 마지막 사용 후 24시간), 7일 비활성 후 중단, 그리고 놀랍도록 효과적인 소극적 공격적 작별 알림. 올빼미 마스코트는 밈이 되었어요."}, {"title": "The 80-90% Rule", "titleKo": "80-90% 법칙", "startSegment": 164, "endSegment": 200, "summary": "Luis argues that educational apps don''t need to be as engaging as TikTok -- 80-90% is enough because internal motivation fills the gap. Duolingo now has more language learners in the US than all high schools combined. He envisions a future where screen time delivers high-quality education to everyone.", "summaryKo": "루이스는 교육 앱이 틱톡만큼 몰입하게 할 필요가 없다고 주장해요. 80-90%면 충분하고 내적 동기가 나머지를 채워준다고요. 듀오링고는 현재 미국 전체 고등학교보다 더 많은 언어 학습자를 보유하고 있어요. 스크린 타임이 모두에게 양질의 교육을 전달하는 미래를 그려요."}, {"title": "Q&A: Applying to Other Subjects", "titleKo": "Q&A: 다른 과목에의 적용", "startSegment": 201, "endSegment": 233, "summary": "In the Q&A session, Luis explains that the Duolingo approach works best for subjects learned through repetition (reading, elementary math). For explanatory content, video-based approaches like Khan Academy may be needed.", "summaryKo": "Q&A에서 루이스는 듀오링고 방식이 반복으로 배우는 과목(읽기, 초등 수학)에 가장 잘 맞는다고 설명해요. 설명이 필요한 콘텐츠에는 칸 아카데미 같은 영상 기반 접근이 필요할 수 있대요."}], "signalExpressions": [{"expression": "So, I''m from Guatemala. This is a public service announcement.", "function": "Opening hook with humor", "functionKo": "유머로 청중의 관심을 끄는 도입부 -- 가벼운 분위기로 시작해요", "segmentIndex": 0}, {"expression": "And a lot of people talk about education as something that brings equality", "function": "Introducing a commonly held belief before challenging it", "functionKo": "일반적으로 받아들여지는 믿음을 소개한 뒤 반박하는 구조예요", "segmentIndex": 10}, {"expression": "Oh, by the way, this is what I want to talk to you about today", "function": "Explicitly stating the main topic after the personal story", "functionKo": "개인 이야기 후 오늘의 주제를 명시적으로 밝히는 표현이에요", "segmentIndex": 25}, {"expression": "And let me tell you why", "function": "Signaling that a justification or explanation follows", "functionKo": "이유나 설명이 뒤따를 것임을 알리는 전환 표현이에요", "segmentIndex": 37}, {"expression": "However, if you''re trying to deliver education with a smartphone", "function": "Introducing a major obstacle or counterpoint", "functionKo": "주요 장애물이나 반론을 소개하는 역접 전환어예요", "segmentIndex": 85}, {"expression": "Let me give you some examples of these techniques", "function": "Transitioning from theory to concrete examples", "functionKo": "이론에서 구체적인 예시로 전환하는 표현이에요", "segmentIndex": 102}, {"expression": "And this is a really important point, let me say this", "function": "Emphasizing a key insight before delivering it", "functionKo": "핵심 통찰을 전달하기 전에 중요성을 강조하는 표현이에요", "segmentIndex": 164}, {"expression": "My hope is that", "function": "Transitioning to a forward-looking vision for the future", "functionKo": "미래에 대한 비전으로 전환하며 희망을 제시하는 표현이에요", "segmentIndex": 188}, {"expression": "But the single most important thing that I can end this talk with", "function": "Signaling the conclusion with a call to action", "functionKo": "행동 촉구와 함께 결론을 알리는 마무리 표현이에요", "segmentIndex": 196}, {"expression": "How do you think that you can apply this type of thinking to other subjects?", "function": "Q&A transition -- interviewer prompts deeper discussion", "functionKo": "Q&A 전환 -- 인터뷰어가 더 깊은 논의를 유도하는 질문이에요", "segmentIndex": 203}]}'::jsonb WHERE language = 'en' AND video_id = 'P6FORpg0KVo';
UPDATE public.video_artifacts SET structure = '{"sections": [{"section": "Introduction - The Facebook Friend", "startSegment": 0, "endSegment": 8, "summary": "Amy opens with a relatable story about a Facebook friend whose life appears perfect, establishing an emotional connection with the audience through shared experience.", "summaryKo": "에이미는 완벽한 삶을 사는 것처럼 보이는 페이스북 친구에 대한 공감할 수 있는 이야기로 시작하며, 공유된 경험을 통해 청중과 감정적 연결을 설정합니다.", "keyPoints": ["완벽해 보이는 삶을 사는 페이스북 친구 소개", "소셜 미디어에서의 비교 심리를 활용한 청중 공감 형성"], "titleKo": "에이미는 완벽한 삶을 사는 것처럼 보이는 페이스…"}, {"section": "Audience Engagement - The Cost of Bad Habits", "startSegment": 9, "endSegment": 23, "summary": "She engages the audience with rhetorical questions and reveals that envying friends on Facebook leads to depression, introducing the concept that our bad mental habits cost us.", "summaryKo": "수사적 질문으로 청중을 참여시키고, 페이스북에서 친구를 부러워하는 것이 우울증으로 이어진다는 것을 밝히며, 나쁜 정신적 습관이 대가를 치르게 한다는 개념을 소개합니다.", "keyPoints": ["페이스북 질투가 실제로 우울증을 유발한다는 연구 결과", "작아 보이는 생각 습관이 정신적 강인함을 갉아먹음"], "titleKo": "수사적 질문으로 청중을 참여시키고, 페이스북에서…"}, {"section": "Three Destructive Beliefs - Part 1: About Ourselves", "startSegment": 24, "endSegment": 35, "summary": "Amy introduces the three types of destructive beliefs, starting with unhealthy beliefs about ourselves, specifically self-pity and how it keeps us stuck.", "summaryKo": "에이미는 세 가지 유형의 파괴적인 믿음을 소개하며, 자기 자신에 대한 건강하지 못한 믿음, 특히 자기연민과 그것이 어떻게 우리를 막히게 하는지 시작합니다.", "keyPoints": ["자기연민은 불행을 과장하는 것", "자기연민 파티를 열면 문제 해결에서 멀어짐"], "titleKo": "에이미는 세 가지 유형의 파괴적인 믿음을 소개하…"}, {"section": "Three Destructive Beliefs - Part 2: About Others", "startSegment": 36, "endSegment": 45, "summary": "The second destructive belief is about others - thinking they can control us. She illustrates how phrases like ''I have to'' and ''she drives me crazy'' give away our power.", "summaryKo": "두 번째 파괴적인 믿음은 다른 사람들에 대한 것으로, 그들이 우리를 통제할 수 있다고 생각하는 것입니다. ''해야 해''와 ''미치게 만들어'' 같은 표현이 우리의 권한을 내어주는 것을 설명합니다.", "keyPoints": ["''해야 한다''는 표현이 자신의 권한을 포기하는 것", "다른 사람에 대한 반응은 항상 자신의 선택"], "titleKo": "두 번째 파괴적인 믿음은 다른 사람들에 대한 것…"}, {"section": "Three Destructive Beliefs - Part 3: About the World", "startSegment": 46, "endSegment": 55, "summary": "The third destructive belief is that the world owes us something. Amy argues that expecting cosmic rewards for hard work leads to disappointment.", "summaryKo": "세 번째 파괴적인 믿음은 세상이 우리에게 무언가 빚지고 있다는 것입니다. 열심히 일한 대가로 우주적 보상을 기대하는 것은 실망만 가져온다고 주장합니다.", "keyPoints": ["성공이 자동으로 따라올 거라는 기대는 실망을 초래", "정신적 강인함을 모두 끌어모아야 할 때가 올 것"], "titleKo": "세 번째 파괴적인 믿음은 세상이 우리에게 무언가…"}, {"section": "Personal Story - Loss of Mother", "startSegment": 56, "endSegment": 72, "summary": "Amy shares her deeply personal story of losing her mother to a brain aneurysm at age 51, when Amy was just 23, and the long healing process.", "summaryKo": "에이미는 23살 때 51세의 어머니를 뇌동맥류로 잃은 매우 개인적인 이야기와 긴 치유 과정을 공유합니다.", "keyPoints": ["23살에 뇌동맥류로 51세 어머니를 잃음", "아는 것과 실천하는 것은 다르다는 깨달음"], "titleKo": "에이미는 23살 때 51세의 어머니를 뇌동맥류로…"}, {"section": "Personal Story - Loss of Husband", "startSegment": 73, "endSegment": 93, "summary": "On the three-year anniversary of her mother''s death, Amy''s husband Lincoln suddenly collapses and dies of a heart attack at age 26, leaving her a young widow.", "summaryKo": "어머니 사망 3주년에 남편 링컨이 26세에 갑작스런 심장마비로 사망하여, 젊은 과부가 됩니다.", "keyPoints": ["어머니 기일에 남편의 갑작스러운 심장마비 사망", "26세 과부가 되어 엄마도 없는 상황"], "titleKo": "어머니 사망 3주년에 남편 링컨이 26세에 갑작…"}, {"section": "The Turning Point - Mental Strength List", "startSegment": 94, "endSegment": 113, "summary": "Amy explains how she realized good habits alone aren''t enough during tough times. After remarrying and facing yet another loss, she wrote her famous list of things mentally strong people don''t do.", "summaryKo": "에이미는 힘든 시기에 좋은 습관만으로는 충분하지 않다는 것을 깨달았다고 설명합니다. 재혼 후 또 다른 상실에 직면하여 정신적으로 강한 사람들이 하지 않는 것들의 유명한 목록을 작성했습니다.", "keyPoints": ["나쁜 습관 하나 둘이면 충분히 발목을 잡을 수 있음", "정신적으로 강한 사람들이 하지 않는 것 목록 작성"], "titleKo": "에이미는 힘든 시기에 좋은 습관만으로는 충분하지…"}, {"section": "Core Message - Mental vs Physical Strength Analogy", "startSegment": 114, "endSegment": 121, "summary": "Amy draws a powerful analogy between mental and physical strength, arguing that just as physical fitness requires both exercise and giving up junk food, mental strength requires good habits and eliminating bad ones.", "summaryKo": "에이미는 정신적 강인함과 신체적 강인함 사이의 강력한 비유를 그립니다. 체력이 운동과 정크 푸드 포기를 모두 필요로 하듯이, 정신적 강인함도 좋은 습관과 나쁜 습관 제거를 필요로 한다고 주장합니다.", "keyPoints": ["정신적 강인함은 신체적 강인함과 같은 원리", "좋은 습관 형성과 나쁜 습관 제거 모두 필요"], "titleKo": "에이미는 정신적 강인함과 신체적 강인함 사이의…"}, {"section": "Solutions - Countering Unhealthy Beliefs", "startSegment": 122, "endSegment": 144, "summary": "Amy provides practical solutions for each type of destructive belief: face uncomfortable emotions instead of avoiding them, stop comparing yourself to others, and accept that life isn''t fair.", "summaryKo": "에이미는 각 유형의 파괴적인 믿음에 대한 실질적인 해결책을 제공합니다: 불편한 감정을 피하는 대신 직면하기, 다른 사람과 비교를 멈추기, 인생이 공평하지 않다는 것 받아들이기.", "keyPoints": ["불편한 감정을 겪어야 극복할 수 있음", "자신을 비교할 유일한 대상은 어제의 나", "인생의 불공평함을 받아들이면 해방감을 얻음"], "titleKo": "에이미는 각 유형의 파괴적인 믿음에 대한 실질적…"}, {"section": "Case Study - The Diabetic Man", "startSegment": 145, "endSegment": 175, "summary": "Amy illustrates her points with a compelling case study of a diabetic man who believed he was doomed, but transformed his life through one small change at a time.", "summaryKo": "에이미는 운명이라고 믿었지만 한 번에 하나의 작은 변화를 통해 삶을 변화시킨 당뇨병 남성의 설득력 있는 사례 연구로 자신의 주장을 설명합니다.", "keyPoints": ["작은 변화 하나가 큰 변화의 시작이 될 수 있음", "자신의 세상을 바꿀 수 있다고 믿는 것의 중요성", "펩시 하나를 바꾸는 것에서 시작하여 운전면허 회복까지"], "titleKo": "에이미는 운명이라고 믿었지만 한 번에 하나의 작…"}, {"section": "Conclusion - Call to Action", "startSegment": 176, "endSegment": 179, "summary": "Amy concludes by inviting the audience to identify their own bad mental habits and take one small step today.", "summaryKo": "에이미는 청중에게 자신의 나쁜 정신적 습관을 파악하고 오늘 하나의 작은 발걸음을 내딛으라고 권하며 마무리합니다.", "keyPoints": ["자신을 막는 나쁜 정신적 습관 파악하기", "오늘 바로 지금 하나의 작은 발걸음 내딛기"], "titleKo": "에이미는 청중에게 자신의 나쁜 정신적 습관을 파…"}], "signalExpressions": [{"expression": "So I have a Facebook friend whose life seems perfect.", "type": "hook", "segmentIndex": 0, "role": "개인적 이야기로 시작하여 청중의 관심을 즉시 끌어들이는 도입 훅"}, {"expression": "And that''s what I want to talk to you about today", "type": "transition", "segmentIndex": 13, "role": "일화에서 주제 제시로 전환하는 신호 표현"}, {"expression": "There''s three kinds of destructive beliefs", "type": "transition", "segmentIndex": 24, "role": "핵심 내용의 구조를 미리 알려주는 로드맵 제시"}, {"expression": "The first one is unhealthy beliefs about ourselves.", "type": "transition", "segmentIndex": 26, "role": "첫 번째 핵심 포인트를 명확히 도입하는 순서 표현"}, {"expression": "The second type of destructive belief that holds us back", "type": "transition", "segmentIndex": 36, "role": "두 번째 핵심 포인트로 전환하는 순서 표현"}, {"expression": "The third type of unhealthy belief that holds us back", "type": "transition", "segmentIndex": 46, "role": "세 번째 핵심 포인트로 전환하는 순서 표현"}, {"expression": "When I was 23 years old, I thought I had life all figured out.", "type": "hook", "segmentIndex": 56, "role": "개인적 이야기의 시작을 알리는 서사적 전환"}, {"expression": "That all changed for me one day", "type": "transition", "segmentIndex": 61, "role": "극적인 전환점을 알리는 서사적 신호"}, {"expression": "My journey taught me that the secret to being mentally strong", "type": "transition", "segmentIndex": 112, "role": "개인적 이야기에서 핵심 교훈으로 전환"}, {"expression": "Mental strength is a lot like physical strength.", "type": "transition", "segmentIndex": 114, "role": "비유를 사용한 핵심 메시지 전달의 시작"}, {"expression": "So, how do you train your brain to think differently?", "type": "transition", "segmentIndex": 120, "role": "문제에서 해결책으로 전환하는 수사적 질문"}, {"expression": "I once worked with this man who had been diabetic for years.", "type": "hook", "segmentIndex": 146, "role": "사례 연구를 도입하는 서사적 시작"}, {"expression": "And it all started with just one small step.", "type": "conclusion", "segmentIndex": 175, "role": "사례 연구를 마무리하며 핵심 메시지를 강조"}, {"expression": "So I invite you to consider what bad mental habits are holding you back.", "type": "conclusion", "segmentIndex": 176, "role": "청중에게 직접 행동을 촉구하는 결론 시작"}, {"expression": "And what''s one small step that you could take today, right here, right now?", "type": "conclusion", "segmentIndex": 178, "role": "즉각적인 행동을 촉구하며 강력하게 마무리하는 최종 질문"}]}'::jsonb WHERE language = 'en' AND video_id = 'TFbv757kup4';
UPDATE public.video_artifacts SET structure = '{"sections": [{"section": "Introduction", "startSegment": 0, "endSegment": 1, "summary": "Steve Jobs opens by stating he will share three stories from his life, setting a simple and direct tone for the speech.", "summaryKo": "스티브 잡스가 자신의 인생에서 세 가지 이야기를 나누겠다고 말하며, 연설의 간결하고 직접적인 톤을 설정합니다.", "keyPoints": ["세 가지 이야기 구조 제시", "겸손하고 친근한 도입"], "titleKo": "스티브 잡스가 자신의 인생에서 세 가지 이야기를…"}, {"section": "Story 1: Connecting the Dots - Birth & Adoption", "startSegment": 1, "endSegment": 12, "summary": "Jobs shares the story of his adoption, explaining how his biological mother wanted him raised by college graduates, and the circumstances that led to his adoption by his parents.", "summaryKo": "잡스가 입양 이야기를 나누며, 생모가 대학 졸업자에 의해 양육되기를 원했던 것과 부모님에게 입양되기까지의 상황을 설명합니다.", "keyPoints": ["생모의 입양 결정", "입양 부모의 대학 진학 약속", "운명적인 시작"], "titleKo": "잡스가 입양 이야기를 나누며, 생모가 대학 졸업…"}, {"section": "Story 1: Connecting the Dots - Dropping Out", "startSegment": 13, "endSegment": 25, "summary": "Jobs describes his decision to drop out of Reed College due to the financial burden and lack of direction, and how dropping in on classes he enjoyed (like calligraphy) proved valuable later.", "summaryKo": "잡스가 재정적 부담과 방향 부재로 리드 대학을 중퇴한 결정과, 서예 같은 좋아하는 수업에 청강한 것이 나중에 가치 있는 것으로 입증된 과정을 설명합니다.", "keyPoints": ["등록금 부담으로 인한 중퇴 결정", "청강생으로서의 경험", "호기심과 직감을 따르는 삶"], "titleKo": "잡스가 재정적 부담과 방향 부재로 리드 대학을…"}, {"section": "Story 1: Connecting the Dots - Calligraphy & Mac", "startSegment": 26, "endSegment": 38, "summary": "Jobs connects his calligraphy education at Reed to the typography of the Macintosh, showing how seemingly unrelated experiences became foundational to Apple''s innovation.", "summaryKo": "잡스가 리드에서의 서예 교육을 매킨토시의 타이포그래피와 연결하며, 관련 없어 보이는 경험이 애플의 혁신의 기반이 된 과정을 보여줍니다.", "keyPoints": ["서예 수업의 영향", "매킨토시의 아름다운 타이포그래피", "예상치 못한 연결"], "titleKo": "잡스가 리드에서의 서예 교육을 매킨토시의 타이포…"}, {"section": "Story 1: Connecting the Dots - Lesson", "startSegment": 39, "endSegment": 44, "summary": "Jobs delivers the key lesson: you cannot connect the dots looking forward, only backward. You must trust that things will work out, follow your heart, and believe the dots will connect.", "summaryKo": "잡스가 핵심 교훈을 전달합니다: 앞을 보며 점을 연결할 수 없고, 뒤돌아볼 때만 가능합니다. 모든 것이 잘 될 것을 믿고, 마음을 따르고, 점들이 연결될 것을 믿어야 합니다.", "keyPoints": ["점 연결은 뒤돌아볼 때만 가능", "직감과 마음을 신뢰하라", "잘 닦인 길을 벗어나는 용기"], "titleKo": "잡스가 핵심 교훈을 전달합니다: 앞을 보며 점을…"}, {"section": "Story 2: Love and Loss - Apple''s Rise", "startSegment": 45, "endSegment": 52, "summary": "Jobs recounts building Apple from a garage to a $2 billion company, then being fired at age 30 after a power struggle with the board of directors.", "summaryKo": "잡스가 차고에서 시작해 20억 달러 회사로 애플을 키운 후, 이사회와의 권력 다툼 끝에 30세에 해고된 이야기를 전합니다.", "keyPoints": ["차고에서 시작한 애플의 성장", "경영진 갈등", "30세에 해고"], "titleKo": "잡스가 차고에서 시작해 20억 달러 회사로 애플…"}, {"section": "Story 2: Love and Loss - Devastation & Recovery", "startSegment": 53, "endSegment": 68, "summary": "Jobs describes the devastation of being fired, how he considered leaving Silicon Valley, but eventually started NeXT and Pixar, and returned to Apple through a remarkable turn of events.", "summaryKo": "잡스가 해고의 충격, 실리콘 밸리를 떠나려 했던 것, 결국 넥스트와 픽사를 시작한 것, 그리고 놀라운 반전으로 애플에 복귀한 과정을 설명합니다.", "keyPoints": ["해고의 충격과 좌절", "넥스트와 픽사 설립", "애플 복귀와 르네상스"], "titleKo": "잡스가 해고의 충격, 실리콘 밸리를 떠나려 했던…"}, {"section": "Story 2: Love and Loss - Lesson", "startSegment": 69, "endSegment": 76, "summary": "Jobs shares the lesson: don''t lose faith, find what you love, and don''t settle. Great work comes from loving what you do, and this applies to careers and relationships alike.", "summaryKo": "잡스가 교훈을 나눕니다: 신념을 잃지 말고, 사랑하는 것을 찾고, 안주하지 마세요. 위대한 일은 하는 일을 사랑하는 데서 나오며, 이는 직업과 관계 모두에 적용됩니다.", "keyPoints": ["사랑하는 일을 찾으라", "안주하지 말라", "위대한 일은 사랑에서 나온다"], "titleKo": "잡스가 교훈을 나눕니다: 신념을 잃지 말고, 사…"}, {"section": "Story 3: Death - Living with Awareness", "startSegment": 77, "endSegment": 86, "summary": "Jobs shares how confronting mortality shaped his daily decisions. He describes his habit of asking whether he would still want to do today''s activities if it were his last day.", "summaryKo": "잡스가 죽음에 대한 인식이 일상의 결정을 어떻게 형성했는지 나눕니다. 오늘이 마지막 날이라면 오늘의 활동을 여전히 하고 싶은지 묻는 습관을 설명합니다.", "keyPoints": ["매일 거울 앞에서의 질문", "죽음 앞에서 사라지는 두려움", "이미 잃을 것이 없다는 깨달음"], "titleKo": "잡스가 죽음에 대한 인식이 일상의 결정을 어떻게…"}, {"section": "Story 3: Death - Death as Life''s Invention", "startSegment": 87, "endSegment": 91, "summary": "Jobs reflects on death as life''s greatest invention and change agent, clearing out the old to make way for the new.", "summaryKo": "잡스가 죽음을 생명의 가장 위대한 발명이자 변화의 동력으로 성찰하며, 낡은 것을 치우고 새것을 위한 자리를 만드는 것으로 설명합니다.", "keyPoints": ["죽음은 생명의 변화 동력", "낡은 것을 치우고 새것을 위한 자리", "삶의 순환"], "titleKo": "잡스가 죽음을 생명의 가장 위대한 발명이자 변화…"}, {"section": "Conclusion - Follow Your Heart", "startSegment": 92, "endSegment": 96, "summary": "Jobs concludes with his most powerful advice: don''t waste time living someone else''s life, don''t be trapped by dogma, follow your heart and intuition, and stay hungry, stay foolish.", "summaryKo": "잡스가 가장 강력한 조언으로 마무리합니다: 다른 사람의 인생을 사는 데 시간을 낭비하지 말고, 독단에 갇히지 말고, 마음과 직감을 따르고, 항상 갈망하고 우직하게 나아가세요.", "keyPoints": ["시간 낭비하지 말라", "독단에 갇히지 말라", "마음과 직감을 따르라", "Stay hungry. Stay foolish."], "titleKo": "잡스가 가장 강력한 조언으로 마무리합니다: 다른…"}], "signalExpressions": [{"expression": "Today I want to tell you three stories from my life.", "type": "hook", "segmentIndex": 0, "role": "연설의 구조를 미리 알려주는 도입부. 청중에게 세 가지 이야기를 예고하여 기대감을 형성합니다."}, {"expression": "The first story is about connecting the dots.", "type": "transition", "segmentIndex": 1, "role": "첫 번째 이야기로의 전환. 주제를 명확히 제시하여 청중이 따라갈 수 있도록 합니다."}, {"expression": "Let me give you one example.", "type": "transition", "segmentIndex": 25, "role": "추상적인 주장에서 구체적인 사례로 전환. 청중의 이해를 돕기 위한 신호입니다."}, {"expression": "Again, you can''t connect the dots looking forward.", "type": "transition", "segmentIndex": 40, "role": "핵심 메시지를 반복하여 강조하는 전환 표현. 이야기에서 교훈으로 넘어가는 신호입니다."}, {"expression": "My second story is about love and loss.", "type": "transition", "segmentIndex": 45, "role": "두 번째 이야기로의 전환. 새로운 주제를 명확히 제시합니다."}, {"expression": "In a remarkable turn of events", "type": "transition", "segmentIndex": 66, "role": "이야기의 극적인 반전을 알리는 전환 표현. 청중의 관심을 다시 집중시킵니다."}, {"expression": "If you haven''t found it yet, keep looking and don''t settle.", "type": "conclusion", "segmentIndex": 74, "role": "두 번째 이야기의 핵심 교훈을 전달하는 결론 표현. 청중에게 직접적인 조언을 합니다."}, {"expression": "My third story is about death.", "type": "transition", "segmentIndex": 77, "role": "세 번째이자 마지막 이야기로의 전환. 가장 무거운 주제를 담담하게 소개합니다."}, {"expression": "Your time is limited, so don''t waste it living someone else''s life.", "type": "conclusion", "segmentIndex": 92, "role": "연설의 최종 메시지를 전달하는 결론부. 모든 이야기를 하나의 교훈으로 종합합니다."}, {"expression": "Stay hungry. Stay foolish.", "type": "conclusion", "segmentIndex": 96, "role": "연설의 마지막 문장이자 가장 유명한 인용구. 간결하면서도 강렬한 마무리로 청중에게 깊은 인상을 남깁니다."}]}'::jsonb WHERE language = 'en' AND video_id = 'Tuw8hxrFBH8';
UPDATE public.video_artifacts SET structure = '{"sections": [{"section": "intro", "startSegment": 0, "endSegment": 7, "summary": "Beth and Neil introduce the topic. Neil is exhausted from a busy day while Beth has been doing nothing. Beth introduces the surprising idea that most animals spend most of their time being inactive, setting up the central question: why have animals evolved to do nothing, and could laziness benefit humans too?", "summaryKo": "베스와 닐이 주제를 소개해요. 닐은 바쁜 하루에 지쳐 있는 반면 베스는 아무것도 하지 않고 있었어요. 베스는 대부분의 동물이 대부분의 시간을 비활동 상태로 보낸다는 놀라운 사실을 소개하며, 왜 동물들이 아무것도 하지 않도록 진화했는지, 게으름이 인간에게도 도움이 될 수 있는지라는 핵심 질문을 던져요.", "keyPoints": ["Contrast between Neil''s busy day and Beth doing nothing", "Most animals spend most of their time doing nothing", "Central question: can laziness benefit humans?"], "titleKo": "베스와 닐이 주제를 소개"}, {"section": "body", "startSegment": 8, "endSegment": 12, "summary": "Beth asks a quiz question about the slowest animal on earth. The discussion reveals that even ants, known for being busy, spend half their time doing nothing. Professor Dan Charbonneau''s research on ant colonies is introduced.", "summaryKo": "베스가 지구에서 가장 느린 동물에 대한 퀴즈를 내요. 부지런한 것으로 알려진 개미조차 절반의 시간을 아무것도 하지 않고 보낸다는 사실이 밝혀져요. 댄 샤르보노 교수의 개미 군체 연구가 소개돼요.", "keyPoints": ["Quiz: what is the slowest moving animal on earth?", "Even busy ants spend half their time motionless", "Introduction of Professor Dan Charbonneau''s ant research"], "titleKo": "베스가 지구에서 가장 느린 동물에 대한 퀴즈를…"}, {"section": "body", "startSegment": 13, "endSegment": 19, "summary": "The expert discussion reveals that ants are viewed as symbols of industriousness, yet about half of any colony is inactive at any time. Possible explanations are explored: inactive ants may be reserves for emergencies, or they may simply not need to work. The parallel to human behaviour is drawn.", "summaryKo": "전문가 토론에서 개미가 근면함의 상징으로 여겨지지만 실제로 군체의 약 절반이 항상 비활동 상태라는 것이 밝혀져요. 비활동 개미가 비상시를 위한 예비 인력일 수 있다는 가능한 설명이 탐구되고, 인간 행동과의 유사점이 제시돼요.", "keyPoints": ["Ants symbolize industriousness but half are inactive", "Inactive ants may serve as reserves for emergencies", "Parallel drawn to human reluctance to work unnecessarily"], "titleKo": "전문가 토론에서 개미가 근면함의 상징으로 여겨지…"}, {"section": "body", "startSegment": 20, "endSegment": 29, "summary": "Psychologist Dr Sandy Mann argues that being productive is overrated and that boredom has important benefits. She suggests boredom fuels curiosity and invention, coining the idea ''boredom is the mother of invention.'' However, constant stimulation from modern technology makes it harder to switch off. The paradox: to overcome boredom, we should actually allow more of it.", "summaryKo": "심리학자 샌디 만 박사는 생산적인 것이 과대평가되어 있으며 지루함에 중요한 장점이 있다고 주장해요. 지루함이 호기심과 발명을 촉진한다며 ''지루함이 발명의 어머니''라는 생각을 제시해요. 하지만 현대 기술의 끊임없는 자극이 머리를 쉬게 하는 것을 더 어렵게 만들어요. 역설: 지루함을 극복하려면 오히려 더 많은 지루함을 허용해야 해요.", "keyPoints": ["Being productive is overrated according to Dr Sandy Mann", "Boredom fuels curiosity and invention", "Modern technology''s constant stimulation prevents switching off", "Paradox: allow more boredom to overcome boredom"], "titleKo": "심리학자 샌디 만 박사는 생산적인 것이 과대평가…"}, {"section": "conclusion", "startSegment": 30, "endSegment": 41, "summary": "Beth reveals the quiz answer (three-toed sloth) and the presenters recap the key vocabulary: kicking back, industrious, colony, productive, necessity is the mother of invention, and switch off. The programme ends with a light-hearted encouragement to do nothing.", "summaryKo": "베스가 퀴즈 정답(세 발가락 나무늘보)을 공개하고 진행자들이 핵심 어휘를 복습해요: kicking back, industrious, colony, productive, necessity is the mother of invention, switch off. 프로그램은 아무것도 하지 말라는 가벼운 격려로 마무리돼요.", "keyPoints": ["Quiz answer: three-toed sloth (30cm per minute, algae grows on coat)", "Vocabulary recap of six key terms", "Light-hearted closing: encouragement to do nothing"], "titleKo": "베스가 퀴즈 정답(세 발가락 나무늘보)을 공개하…"}], "signalExpressions": [{"expression": "Phew, I''ve spent a day in meetings", "type": "emphasis", "segmentIndex": 1, "role": "바쁜 일상을 생생하게 보여주며 주제(아무것도 하지 않기)와의 대비를 만들어요"}, {"expression": "It may not look it, Neil, but", "type": "transition", "segmentIndex": 5, "role": "겉보기와 실제의 차이를 소개하며 동물 세계의 놀라운 사실로 전환해요"}, {"expression": "But the surprising truth is", "type": "emphasis", "segmentIndex": 6, "role": "청중의 기대를 뒤집는 핵심 사실을 강조하며 소개해요"}, {"expression": "That''s what we''ll be discussing in this programme", "type": "transition", "segmentIndex": 7, "role": "프로그램의 방향을 안내하며 본격적인 논의로 전환해요"}, {"expression": "But first, let me work up the energy to ask you a question", "type": "transition", "segmentIndex": 8, "role": "유머러스하게 퀴즈 코너를 소개하며 주제와 연결해요"}, {"expression": "Here''s Professor Dan Charbonneau", "type": "transition", "segmentIndex": 11, "role": "외부 전문가의 목소리를 도입하며 과학적 근거로 전환해요"}, {"expression": "But then when you look at it", "type": "transition", "segmentIndex": 15, "role": "이상과 현실의 차이를 드러내며 놀라운 연구 결과로 전환해요"}, {"expression": "Not according to psychologist Dr Sandy Mann", "type": "transition", "segmentIndex": 20, "role": "새로운 전문가 관점을 소개하며 지루함의 장점이라는 새 소주제로 전환해요"}, {"expression": "But in this world of constant stimulation", "type": "transition", "segmentIndex": 24, "role": "이론에서 현대 사회의 현실적 문제로 전환해요"}, {"expression": "So it''s a kind of paradox", "type": "summary", "segmentIndex": 26, "role": "앞선 논의를 역설적 결론으로 요약하며 핵심 메시지를 전달해요"}, {"expression": "I think now is a good time to reveal the answer", "type": "transition", "segmentIndex": 30, "role": "본론에서 마무리 단계로 자연스럽게 전환해요"}, {"expression": "OK, let''s recap the vocabulary", "type": "summary", "segmentIndex": 33, "role": "프로그램의 학습 목표를 정리하며 어휘 복습 코너로 전환해요"}]}'::jsonb WHERE language = 'en' AND video_id = 'Y681hXWwhQY';
UPDATE public.video_artifacts SET structure = '{"sections": [{"section": "Introduction - The Question", "startSegment": 0, "endSegment": 3, "summary": "Poses the central question: what do diverse English dialects, Chaucer''s writings, and Beowulf have in common?", "summaryKo": "핵심 질문을 제시합니다: 다양한 영어 방언, 초서의 글, 베오울프가 어떤 공통점을 가지고 있을까요?", "keyPoints": ["영어를 단일 언어로 생각하지만 실제로는 다양한 방언이 있음", "현대 영어와 고대 문학 사이의 관계에 대한 질문 제기"], "titleKo": "핵심 질문을 제시합니다: 다양한 영어 방언, 초…"}, {"section": "Core Answer - Language Evolution", "startSegment": 4, "endSegment": 9, "summary": "Explains that English, like most languages, has evolved over generations. Modern English shares words with Romance languages, but most were borrowed later.", "summaryKo": "영어가 대부분의 언어처럼 세대를 거치며 진화해 왔음을 설명합니다. 현대 영어가 로망스어와 단어를 공유하지만, 대부분은 나중에 차용된 것입니다.", "keyPoints": ["영어는 여러 세대에 걸쳐 진화해 왔음", "라틴어 파생 로망스어와 유사한 단어는 원래 영어의 일부가 아니었음"], "titleKo": "영어가 대부분의 언어처럼 세대를 거치며 진화해…"}, {"section": "Norman Invasion and French Influence", "startSegment": 10, "endSegment": 16, "summary": "Describes how the Norman invasion of 1066 brought French and Latin vocabulary into Old English.", "summaryKo": "1066년 노르만 침공이 프랑스어와 라틴어 어휘를 고대 영어에 가져온 과정을 설명합니다.", "keyPoints": ["1066년 노르만족의 잉글랜드 침공", "프랑스어를 사용하는 지배 계층이 대량의 프랑스어와 라틴어 어휘를 추가", "침공 이전의 언어를 고대 영어라고 부름"], "titleKo": "1066년 노르만 침공이 프랑스어와 라틴어 어휘…"}, {"section": "Old English and Germanic Roots", "startSegment": 17, "endSegment": 23, "summary": "Explains Old English''s Germanic origins, brought by Angles, Saxons, and Jutes, with additional Norse borrowings from Viking invasions.", "summaryKo": "앵글족, 색슨족, 주트족이 가져온 고대 영어의 게르만어 기원과 바이킹 침략으로 인한 노르드어 차용을 설명합니다.", "keyPoints": ["고대 영어는 게르만어족에 속함", "5~6세기에 앵글족, 색슨족, 주트족이 브리튼 제도에 가져옴", "8~11세기 바이킹 침략자들이 고대 노르드어 차용어를 추가"], "titleKo": "앵글족, 색슨족, 주트족이 가져온 고대 영어의…"}, {"section": "Comparative Linguistics Method", "startSegment": 24, "endSegment": 33, "summary": "Introduces comparative linguistics as a tool to trace language origins through grammatical patterns, sound changes, and core vocabulary, with specific examples of P-to-PF and SK-to-SH shifts.", "summaryKo": "문법 패턴, 음운 변화, 핵심 어휘를 통해 언어 기원을 추적하는 도구로서 비교언어학을 소개하며, P에서 PF로, SK에서 SH로의 변화 등 구체적 예를 제시합니다.", "keyPoints": ["비교언어학은 문법 구조, 음운 변화 패턴, 핵심 어휘에 초점", "독일어의 P에서 PF로의 변화 vs 영어의 P 유지", "스웨덴어 SK가 영어에서 SH로 변화", "skirt, skull 같은 단어는 SK-SH 변화 이후의 노르드어 차용어"], "titleKo": "문법 패턴, 음운 변화, 핵심 어휘를 통해 언어…"}, {"section": "Proto-Germanic and Proto-Indo-European", "startSegment": 34, "endSegment": 45, "summary": "Traces the language family tree from Proto-Germanic (500 BCE) to Proto-Indo-European (6,000 years ago), encompassing nearly all European and many Asian languages.", "summaryKo": "원시 게르만어(기원전 500년)에서 인도유럽조어(6,000년 전)까지의 언어 가계도를 추적하며, 거의 모든 유럽 언어와 많은 아시아 언어를 포괄합니다.", "keyPoints": ["영어, 스웨덴어, 독일어 등은 원시 게르만어(기원전 500년경)에서 파생", "원시 게르만어는 기록된 적이 없어 후손 언어 비교로만 재구성 가능", "원시 게르만어는 인도유럽조어에서 유래", "인도유럽조어는 약 6,000년 전 폰투스 초원에서 사용됨"], "titleKo": "원시 게르만어(기원전 500년)에서 인도유럽조어…"}, {"section": "Sound Correspondences Across Indo-European", "startSegment": 46, "endSegment": 52, "summary": "Demonstrates systematic sound correspondences between English and Latin (T/D, F/P), and mentions distant relatives like Hindi, Persian, and Celtic languages.", "summaryKo": "영어와 라틴어 사이의 체계적 음운 대응(T/D, F/P)을 보여주고, 힌디어, 페르시아어, 켈트어 등 먼 친척 언어를 언급합니다.", "keyPoints": ["영어 T = 라틴어 D, 영어 F = 라틴어 P (단어 시작 부분)", "영어의 먼 친척: 힌디어, 페르시아어, 켈트어"], "titleKo": "영어와 라틴어 사이의 체계적 음운 대응(T/D,…"}, {"section": "Conclusion - Remaining Mysteries and Wonder", "startSegment": 53, "endSegment": 60, "summary": "Acknowledges the limits of historical evidence while marveling at the fact that nearly three billion people speak words shaped by 6,000 years of shared history.", "summaryKo": "역사적 증거의 한계를 인정하면서도, 거의 30억 명이 6,000년의 공유된 역사에 의해 형성된 단어들을 사용하고 있다는 놀라운 사실을 강조합니다.", "keyPoints": ["인도유럽조어 이전의 언어는 추적 불가능", "인도유럽어와 다른 어족 사이의 연결 등 미스터리가 남아 있음", "거의 30억 명이 서로 이해할 수 없지만 6,000년 역사로 형성된 같은 단어들을 사용"], "titleKo": "역사적 증거의 한계를 인정하면서도, 거의 30억…"}], "signalExpressions": [{"expression": "When we talk about English, we often think of it as a single language.", "type": "hook", "segmentIndex": 0, "role": "일반적 인식을 제시하여 청중의 흥미를 유발하는 도입부"}, {"expression": "But what do the dialects spoken in dozens of countries...", "type": "hook", "segmentIndex": 1, "role": "수사적 질문으로 호기심을 자극하며 영상의 핵심 주제를 제시"}, {"expression": "The answer is that", "type": "transition", "segmentIndex": 4, "role": "질문에서 설명으로 전환하는 신호 표현"}, {"expression": "Instead", "type": "transition", "segmentIndex": 10, "role": "예상과 다른 사실을 소개하는 전환 표현"}, {"expression": "Today, we call that language Old English.", "type": "transition", "segmentIndex": 16, "role": "역사적 배경에서 구체적인 언어학 용어로 전환"}, {"expression": "That''s because", "type": "transition", "segmentIndex": 19, "role": "이유를 설명하는 인과관계 표현"}, {"expression": "But comparative linguistics can help us", "type": "transition", "segmentIndex": 26, "role": "문제에서 해결책(비교언어학)으로 전환하는 표현"}, {"expression": "For example", "type": "transition", "segmentIndex": 28, "role": "구체적인 예시를 도입하는 신호 표현"}, {"expression": "These examples show us that", "type": "transition", "segmentIndex": 34, "role": "구체적 예시에서 일반적 결론으로 전환"}, {"expression": "We can even use the same process to go back one step further", "type": "transition", "segmentIndex": 40, "role": "논의를 더 깊은 단계로 확장하는 전환 표현"}, {"expression": "But unfortunately, this is as far back as... will allow us to go.", "type": "transition", "segmentIndex": 54, "role": "연구의 한계를 인정하며 결론부로 전환"}, {"expression": "But the amazing fact remains that", "type": "conclusion", "segmentIndex": 58, "role": "한계에도 불구하고 놀라운 결론을 제시하는 마무리 표현"}, {"expression": "Are nevertheless speaking the same words shaped by 6,000 years of history.", "type": "conclusion", "segmentIndex": 60, "role": "6,000년의 공유 역사를 강조하며 감동적으로 마무리"}]}'::jsonb WHERE language = 'en' AND video_id = 'YEaSxhcns7Y';
UPDATE public.video_artifacts SET structure = '{"sections": [{"section": "Personal Crisis: Loneliness and Cultural Lies", "startSegment": 0, "endSegment": 16, "summary": "David Brooks shares his personal crisis in 2013 — his marriage ended, his children left home, and he lost friends. Living alone, consumed by work, he experienced profound loneliness and realized the emptiness in his life reflected the lies our culture tells us.", "summaryKo": "데이비드 브룩스가 2013년의 개인적 위기를 나눠요. 결혼 생활이 끝나고, 아이들이 떠나고, 친구들을 잃었어요. 혼자 살면서 일에만 매달렸고, 깊은 외로움을 경험하며 삶의 공허함이 문화가 말하는 거짓말을 반영한다는 것을 깨달았어요.", "keyPoints": ["Personal crisis: divorce, children leaving, loss of friends", "Loneliness manifested as fear and lack of solidity", "The emptiness outside reflected emptiness within"], "titleKo": "데이비드 브룩스가 2013년의 개인적 위기를 나…"}, {"section": "Three Cultural Lies About Success", "startSegment": 17, "endSegment": 32, "summary": "Brooks identifies three cultural lies: (1) career success is fulfilling, (2) you can make yourself happy through self-sufficiency, and (3) the meritocracy — the belief that your worth equals your accomplishments. He argues that deep relationships, not achievements, create true happiness.", "summaryKo": "브룩스는 세 가지 문화적 거짓말을 지적해요. (1) 직업적 성공이 만족을 준다, (2) 자급자족으로 행복해질 수 있다, (3) 능력주의 — 당신의 가치가 성취와 같다는 믿음이에요. 성취가 아니라 깊은 관계가 진정한 행복을 만든다고 주장해요.", "keyPoints": ["Career success only avoids shame, doesn''t bring positive good", "Self-sufficiency is a lie; deep relationships make people happy", "Meritocracy teaches conditional love and dehumanizing rankings"], "titleKo": "브룩스는 세 가지 문화적 거짓말을 지적"}, {"section": "A National Crisis of Disconnection", "startSegment": 33, "endSegment": 55, "summary": "Brooks describes how his personal valley of disconnection mirrors a national crisis. He presents alarming statistics about loneliness, isolation, depression, and suicide in America, arguing that we face not just economic and environmental crises but a social and relational one.", "summaryKo": "브룩스는 자신의 단절의 골짜기가 국가적 위기를 반영한다고 설명해요. 미국의 외로움, 고립, 우울증, 자살에 관한 충격적인 통계를 제시하며, 경제적 환경적 위기뿐 아니라 사회적이고 관계적인 위기에 직면해 있다고 주장해요.", "keyPoints": ["35% of Americans over 45 are chronically lonely", "Suicide rate has risen 30% since 1999", "Life expectancy is falling — a social and relational crisis exists"], "titleKo": "브룩스는 자신의 단절의 골짜기가 국가적 위기를…"}, {"section": "Three Realizations from the Valley", "startSegment": 56, "endSegment": 88, "summary": "Brooks shares three realizations from his valley: (1) social freedom without roots leads to drift, (2) suffering can break you or break you open to deeper self-knowledge, and (3) the heart yearns for love and fusion with others. He illustrates with the theologian Paul Tillich and a passage from Captain Corelli''s Mandolin.", "summaryKo": "브룩스는 골짜기에서 얻은 세 가지 깨달음을 나눠요. (1) 뿌리 없는 사회적 자유는 방황으로 이끈다, (2) 고통은 부서지게도, 열리게도 할 수 있다, (3) 마음은 사랑과 타인과의 융합을 갈망한다는 거예요. 신학자 폴 틸리히와 코렐리 대위의 만돌린을 인용해요.", "keyPoints": ["Freedom is a river to cross, not an ocean to swim in", "Suffering carves deeper into the soul, revealing unknown depths", "True love is what remains after being in love burns away"], "titleKo": "브룩스는 골짜기에서 얻은 세 가지 깨달음을 나눠…"}, {"section": "The Soul and Infinite Dignity", "startSegment": 89, "endSegment": 113, "summary": "Brooks explores the soul and consciousness. He argues that everyone has a soul of infinite dignity regardless of status. The soul yearns for righteousness while the heart yearns for connection. Borrowing from Einstein, he says problems can''t be solved at the level of consciousness that created them.", "summaryKo": "브룩스는 영혼과 의식을 탐구해요. 지위에 관계없이 모든 사람에게 무한한 존엄성의 영혼이 있다고 주장해요. 영혼은 올바름을 갈망하고 마음은 연결을 갈망해요. 아인슈타인을 인용하여 문제를 만든 의식 수준에서는 문제를 해결할 수 없다고 말해요.", "keyPoints": ["Every person has a soul with infinite dignity and value", "The soul yearns for righteousness, the heart for fusion", "You must expand to a different level of consciousness to solve problems"], "titleKo": "브룩스는 영혼과 의식을 탐구"}, {"section": "Stories of Weavers: Community Builders", "startSegment": 114, "endSegment": 171, "summary": "Brooks shares stories of ''weavers'' — community builders who pull others out of valleys. He describes Kathy and David''s home that welcomed 25 kids, Aisha Butler who chose to stay and rebuild her neighborhood, Sarah who turned tragedy into service, and the Roots of Empathy program that teaches children through caring for an infant.", "summaryKo": "브룩스는 ''위버'' — 다른 사람을 골짜기에서 끌어올리는 공동체 건설자들의 이야기를 나눠요. 25명의 아이를 환영한 캐시와 데이비드의 집, 동네를 재건하기로 한 아이샤 버틀러, 비극을 봉사로 바꾼 세라, 아기 돌봄을 통해 아이들에게 공감을 가르치는 공감의 뿌리 프로그램을 소개해요.", "keyPoints": ["You can''t climb out of a valley alone — someone must reach in", "Weavers live relationist lives with moral motivation and vocational certitude", "Stories of Kathy & David, Aisha Butler, Sarah, and Roots of Empathy"], "titleKo": "브룩스는 ''위버'' — 다른 사람을 골짜기에서 끌…"}, {"section": "Happiness vs. Joy: Dissolving the Self", "startSegment": 172, "endSegment": 209, "summary": "Brooks distinguishes between happiness (expansion of self) and joy (dissolving of self). He uses E.O. Wilson''s childhood awe at nature and Zadie Smith''s ecstatic night at a London club to illustrate joy — moments when self-consciousness disappears and one is fully given over to the experience.", "summaryKo": "브룩스는 행복(자아의 확장)과 기쁨(자아의 용해)을 구분해요. E.O. 윌슨의 자연에 대한 어린 시절의 경외와 재디 스미스의 런던 클럽에서의 황홀한 밤을 통해 기쁨을 설명해요 — 자의식이 사라지고 경험에 완전히 빠지는 순간이에요.", "keyPoints": ["Happiness is expansion of self; joy is dissolving of self", "E.O. Wilson''s childhood encounter with nature illustrates awe and vocation", "Zadie Smith''s nightclub experience captures the surrender to joy"], "titleKo": "브룩스는 행복(자아의 확장)과 기쁨(자아의 용해…"}, {"section": "Two Mindsets: Individual Success vs. Relational Living", "startSegment": 210, "endSegment": 230, "summary": "Brooks contrasts two mindsets: the ''first mountain'' mindset of individual success and the relational mindset needed to heal our national valley. He calls for a cultural and relational revolution, arguing that weavers have found a better way to live, and if we follow their example, both personal emptiness and social fragmentation can be repaired.", "summaryKo": "브룩스는 두 가지 사고방식을 대비해요: 개인적 성공의 ''첫 번째 산'' 사고방식과 국가적 골짜기를 치유하는 데 필요한 관계적 사고방식이에요. 문화적이고 관계적인 혁명을 촉구하며, 위버들이 더 나은 삶의 방식을 찾았고 그 본보기를 따르면 개인의 공허함과 사회적 분열 모두 회복될 수 있다고 주장해요.", "keyPoints": ["Two mindsets: first mountain (individual success) vs. relational living", "We need a cultural and relational revolution, not just economic fixes", "Weavers show a better way — we just need to shift our lives a little"], "titleKo": "브룩스는 두 가지 사고방식을 대비해요: 개인적…"}], "signalExpressions": [{"expression": "So we all have bad seasons in life", "type": "emphasis", "segmentIndex": 0, "role": "청중의 공감을 유도하는 도입부 — 보편적인 경험으로 시작하여 주의를 끌어요"}, {"expression": "And I had one in 2013", "type": "transition", "segmentIndex": 1, "role": "일반적인 이야기에서 개인적 경험으로 전환하며 구체적인 서사를 시작해요"}, {"expression": "The first lie is that career success is fulfilling", "type": "transition", "segmentIndex": 17, "role": "핵심 주장의 첫 번째 항목을 소개하며 논리적 구조를 세워요"}, {"expression": "The second lie is I can make myself happy", "type": "transition", "segmentIndex": 20, "role": "두 번째 거짓말로 전환하며 병렬 구조를 유지해요"}, {"expression": "The third lie is the lie of the meritocracy", "type": "transition", "segmentIndex": 26, "role": "세 번째 거짓말을 소개하며 가장 깊은 분석으로 들어가요"}, {"expression": "So what do I mean to tell you?", "type": "transition", "segmentIndex": 51, "role": "개인 이야기에서 사회적 메시지로 전환하며 강연의 핵심 목적을 밝혀요"}, {"expression": "How do you get out of a valley?", "type": "transition", "segmentIndex": 56, "role": "문제 제기에서 해결책으로 전환하는 수사적 질문이에요"}, {"expression": "The first is, freedom sucks", "type": "emphasis", "segmentIndex": 58, "role": "충격적인 표현으로 주의를 집중시키며 첫 번째 깨달음을 소개해요"}, {"expression": "The second thing I learned is that", "type": "transition", "segmentIndex": 65, "role": "두 번째 깨달음으로 자연스럽게 전환해요"}, {"expression": "The hard thing about when you''re in the valley is", "type": "transition", "segmentIndex": 114, "role": "이론에서 실천적 이야기로 전환하며 위버들의 등장을 준비해요"}, {"expression": "And so what I''m trying to describe is two different live mindsets", "type": "summary", "segmentIndex": 210, "role": "전체 강연의 핵심을 요약하며 결론부로 진입해요"}, {"expression": "My theory of social change is that society changes", "type": "summary", "segmentIndex": 221, "role": "최종 메시지를 전달하며 행동을 촉구하는 마무리를 시작해요"}]}'::jsonb WHERE language = 'en' AND video_id = 'iB4MS1hsWXU';
UPDATE public.video_artifacts SET structure = '{"sections": [{"section": "Introduction", "startSegment": 0, "endSegment": 11, "summary": "The speech opens by emphasizing chocolate''s historical significance, contrasting modern perceptions with its origins in Mesoamerica. It highlights the cultural and religious importance of cacao to ancient civilizations.", "summaryKo": "발표는 초콜릿의 역사적 중요성을 강조하며, 현대의 인식과 마eso아메리카에서의 출처를 대비합니다. 고대 문명에서 초콜릿의 문화적·종교적 중요성을 강조합니다.", "keyPoints": ["Chocolate''s origins in Mesoamerica before the 16th century", "Cacao''s sacred status as a gift from gods", "Cacao''s use as currency and in rituals", "Contrast between ancient and modern chocolate consumption"], "titleKo": "발표는 초콜릿의 역사적 중요성을 강조하며, 현대…"}, {"section": "Historical Development", "startSegment": 12, "endSegment": 33, "summary": "The speech details the spread of cacao from Mesoamerica to Europe, including its adoption by Spanish colonists and the invention of the cocoa press in 1828, which revolutionized chocolate production.", "summaryKo": "초콜릿이 마eso아메리카에서 유럽으로 확산되며, 스페인 식민지인들이 채택하고 1828년 코코아 프레스 발명으로 생산 방식이 혁신되었다는 점을 설명합니다.", "keyPoints": ["Cacao''s journey from Mesoamerica to Europe", "Spanish adaptation of cacao into sweetened chocolate", "Cocoa press invention in 1828", "Industrialization of chocolate production"], "titleKo": "초콜릿이 마eso아메리카에서 유럽으로 확산되며,…"}, {"section": "Modern Issues and Ethics", "startSegment": 34, "endSegment": 55, "summary": "The speech addresses contemporary problems in the chocolate industry, including child labor and slavery in West African cocoa production, and the industry''s ongoing efforts to address these issues.", "summaryKo": "현대 초콜릿 산업에서의 문제, 서아프리카 코코아 재배에서의 어린이 노동과 노예 문제, 그리고 산업의 해결을 위한 노력에 대해 다룹니다.", "keyPoints": ["Child labor and slavery in West African cocoa farms", "Estimates of over 2 million affected children", "Industry partnerships to combat labor abuses", "Persistent ethical challenges despite efforts"], "titleKo": "현대 초콜릿 산업에서의 문제, 서아프리카 코코아…"}, {"section": "Conclusion", "startSegment": 56, "endSegment": 68, "summary": "The speech concludes by reflecting on chocolate''s cultural significance and urging listeners to consider its complex history, ending with repeated ''FINALLY'' phrases to emphasize the message.", "summaryKo": "초콜릿의 문화적 의미를 반성하며, 청중이 초콜릿의 복잡한 역사에 대해 고민하도록 호소하고, ''FINALLY'' 반복으로 메시지를 강조합니다.", "keyPoints": ["Chocolate''s enduring cultural associations", "Reflection on its historical and ethical complexities", "Call to consider the ''not everything about chocolate is sweet'' message", "Repetition of ''FINALLY'' as a closing emphasis"], "titleKo": "초콜릿의 문화적 의미를 반성하며, 청중이 초콜릿…"}], "signalExpressions": [{"expression": "The The The", "type": "hook", "segmentIndex": 0, "role": "발표의 시작을 강조하고 청중의 주의를 끌어당김"}, {"expression": "Yet knowing more about its fascinating and often cruel history", "type": "emphasis", "segmentIndex": 61, "role": "핵심 메시지 강조 — 역사적 맥락이 현대 연관성에 미치는 영향을 강조"}, {"expression": "So as you unwrap your next bar of chocolate", "type": "conclusion", "segmentIndex": 63, "role": "종결적 호소 — 청중에게 사고를 유도하는 마무리"}, {"expression": "FINALLY", "type": "conclusion", "segmentIndex": 64, "role": "강한 마무리 강조 — 메시지의 중요성을 반복 강조"}, {"expression": "The world of chocolate would change forever", "type": "transition", "segmentIndex": 33, "role": "새로운 주제로 전환 — 기술적 혁신으로 이어짐"}, {"expression": "The key is", "type": "emphasis", "segmentIndex": 61, "role": "핵심 메시지 요약 — 역사적 맥락이 현대 연관성에 미치는 영향을 강조"}]}'::jsonb WHERE language = 'en' AND video_id = 'ibjUpk9Iagk';
UPDATE public.video_artifacts SET structure = '{"sections": [{"title": "Introduction: Planning vs. Strategy", "titleKo": "도입: 계획 vs. 전략", "startSegment": 0, "endSegment": 10, "summary": "Roger Martin introduces the key distinction between planning and strategy. He explains that ''strategic planning'' is a misleading term because most strategic planning in business is really just a list of activities with no coherent strategy behind it.", "summaryKo": "로저 마틴이 계획과 전략의 핵심적인 차이를 소개해. ''전략적 계획''이라는 용어가 오해를 불러일으킨다고 설명하면서, 대부분의 전략적 계획은 실제로 일관된 전략 없이 활동 목록을 나열한 것에 불과하다고 말해."}, {"title": "What Strategy Really Is", "titleKo": "전략이란 진짜 무엇인가", "startSegment": 11, "endSegment": 20, "summary": "Martin defines strategy as an integrative set of choices that positions you to win on a chosen playing field. A strategy requires a coherent theory, unlike planning which tends to be a disconnected wish list from different departments.", "summaryKo": "마틴은 전략을 선택한 경쟁의 장에서 이길 수 있도록 포지셔닝하는 통합적 선택의 집합이라고 정의해. 전략은 일관된 이론이 필요한 반면, 계획은 각 부서의 단절된 희망 목록이 되기 쉽다고 설명해."}, {"title": "Why Planning Feels Comfortable", "titleKo": "왜 계획이 편안하게 느껴지는가", "startSegment": 21, "endSegment": 39, "summary": "Martin explains why managers gravitate toward planning: plans deal with costs you control (hiring, building, purchasing), while strategy requires specifying outcomes that depend on customers — whom you cannot control. Strategy is inherently uncertain, which makes it uncomfortable.", "summaryKo": "매니저들이 왜 계획에 끌리는지 설명해. 계획은 채용, 건설, 구매 등 통제 가능한 비용을 다루지만, 전략은 통제할 수 없는 고객에 달린 결과를 명시해야 해. 전략은 본질적으로 불확실하기 때문에 불편하게 느껴져."}, {"title": "The Southwest Airlines Case Study", "titleKo": "사우스웨스트 항공 사례 연구", "startSegment": 40, "endSegment": 60, "summary": "Martin uses Southwest Airlines as a powerful example. While major carriers were busy planning, Southwest developed a winning strategy: be a substitute for Greyhound buses with point-to-point flights, one aircraft type, no meals, and online booking — achieving substantially lower costs and eventually becoming the largest U.S. carrier by passenger seat miles.", "summaryKo": "사우스웨스트 항공을 강력한 사례로 들어. 주요 항공사들이 계획에 바쁜 동안, 사우스웨스트는 그레이하운드 버스의 대체재가 되겠다는 전략을 세웠어. 포인트 투 포인트 비행, 단일 기종, 기내식 없음, 온라인 예약으로 비용을 크게 낮추고 결국 미국 최대 항공사가 됐어."}, {"title": "How to Escape the Planning Trap", "titleKo": "계획의 함정에서 벗어나는 방법", "startSegment": 61, "endSegment": 75, "summary": "Martin offers practical advice for escaping the comfort trap of planning: accept that strategy involves angst and uncertainty, lay out the logic clearly by asking ''what would have to be true,'' and treat strategy as a journey that you continuously tweak and refine.", "summaryKo": "계획의 안주 함정에서 벗어나기 위한 실용적 조언을 제시해. 전략에는 불안과 불확실성이 수반된다는 걸 받아들이고, ''무엇이 사실이어야 하는가''를 물어 논리를 명확히 하고, 전략을 지속적으로 조정하고 개선하는 여정으로 대해야 한다고 말해."}, {"title": "Conclusion: Keep It Simple, Start Winning", "titleKo": "결론: 단순하게, 이기기 시작하라", "startSegment": 76, "endSegment": 85, "summary": "Martin concludes with the advice to keep strategy simple — ideally on a single page — covering where to play, how to win, what capabilities are needed, and what must be true. Planning guarantees losing; strategy gives you the best possible chance of winning.", "summaryKo": "전략을 단순하게 유지하라는 조언으로 마무리해. 어디서 싸울지, 어떻게 이길지, 어떤 역량이 필요한지, 무엇이 사실이어야 하는지를 한 페이지에 담는 것이 이상적이야. 계획만 하면 지는 걸 보장하지만, 전략은 이길 수 있는 최선의 기회를 줘."}], "signalExpressions": [{"expression": "This thing called planning has been around for a long, long time.", "function": "Opening hook", "functionKo": "오래된 개념을 소개하며 청중의 관심을 끄는 도입부", "segmentIndex": 0}, {"expression": "Unfortunately, those things are not the same", "function": "Introducing the core problem", "functionKo": "핵심 문제를 제시하며 계획과 전략의 차이를 부각시키는 전환점", "segmentIndex": 4}, {"expression": "So what''s a strategy?", "function": "Rhetorical question to introduce definition", "functionKo": "수사적 질문으로 전략의 정의를 소개하며 핵심 개념으로 전환", "segmentIndex": 11}, {"expression": "Planning is quite comforting.", "function": "Transition to contrasting argument", "functionKo": "계획의 매력을 인정하면서 왜 사람들이 전략 대신 계획에 안주하는지 설명하는 전환", "segmentIndex": 21}, {"expression": "A strategy, on the other hand", "function": "Contrastive transition", "functionKo": "앞서 설명한 계획과 대비되는 전략의 특성을 소개하는 대조 전환 표현", "segmentIndex": 29}, {"expression": "When U.S. air carriers were busily planning", "function": "Introducing a case study", "functionKo": "사우스웨스트 항공 사례를 도입하며 추상적 개념을 구체적 예시로 전환", "segmentIndex": 41}, {"expression": "If you''re trying to escape this planning trap", "function": "Transition to actionable advice", "functionKo": "이론에서 실행 가능한 조언으로 전환하며 청중에게 직접 말을 거는 표현", "segmentIndex": 61}, {"expression": "The second thing I do is say", "function": "Sequential enumeration", "functionKo": "조언을 순서대로 나열하며 두 번째 핵심 포인트로 넘어가는 구조적 표현", "segmentIndex": 71}, {"expression": "Another thing that helps with strategy is", "function": "Adding a supplementary point", "functionKo": "추가적인 조언을 제시하며 논점을 보충하는 전환 표현", "segmentIndex": 76}, {"expression": "But I would tell you that if you plan, that''s a way to guarantee losing.", "function": "Concluding statement with strong contrast", "functionKo": "강한 대조로 핵심 메시지를 마무리하며 계획과 전략의 결과 차이를 확실히 각인시키는 결론", "segmentIndex": 84}]}'::jsonb WHERE language = 'en' AND video_id = 'iuYlGRnC7J8';
UPDATE public.video_artifacts SET structure = '{"sections": [{"section": "Captain Swenson''s Medal of Honor", "startSegment": 0, "endSegment": 22, "summary": "Simon Sinek opens with the story of Captain William Swenson, who ran into live fire to rescue wounded soldiers in Afghanistan. A GoPro camera captured Swenson kissing a wounded soldier before returning to save more. This powerful image raises the question: where does such selfless love come from?", "summaryKo": "사이먼 사이넥이 아프가니스탄에서 부상병을 구하기 위해 실탄이 오가는 속으로 뛰어든 캡틴 윌리엄 스웬슨의 이야기로 시작해요. 고프로 카메라가 스웬슨이 부상병에게 입맞춤하고 다시 구조하러 돌아가는 장면을 담았어요. 이 강렬한 이미지가 질문을 던져요: 이런 이타적인 사랑은 어디서 오는 걸까?", "keyPoints": ["Captain Swenson received the Congressional Medal of Honor", "He ran into live fire to rescue the wounded", "A GoPro captured his tender moment with a wounded soldier", "Sinek asks: where do people like that come from?"], "titleKo": "사이먼 사이넥이 아프가니스탄에서 부상병을 구하기…"}, {"section": "Environment, Not Better People", "startSegment": 23, "endSegment": 32, "summary": "Sinek contrasts the military, which rewards self-sacrifice, with business, which rewards sacrificing others. His initial assumption was that military heroes are just better people, but he learned the real answer: it''s the environment. With the right conditions, everyone has the capacity for remarkable selflessness.", "summaryKo": "사이넥은 자기 희생을 보상하는 군대와 타인의 희생을 보상하는 비즈니스를 대비해요. 처음에는 군인 영웅들이 그냥 더 나은 사람이라고 생각했지만, 진짜 답은 환경이라는 걸 배웠어요. 올바른 환경이 갖춰지면 모든 사람에게 놀라운 이타심의 능력이 있어요.", "keyPoints": ["Military gives medals for self-sacrifice; business gives bonuses for sacrificing others", "It''s not about better people — it''s about the environment", "The right environment unlocks everyone''s capacity for remarkable things"], "titleKo": "사이넥은 자기 희생을 보상하는 군대와 타인의 희…"}, {"section": "Trust and Cooperation Are Feelings", "startSegment": 33, "endSegment": 44, "summary": "Heroes he interviewed all say the same thing: ''They would have done it for me.'' Trust and cooperation are feelings, not instructions. You cannot simply command people to trust or cooperate — it must come naturally from within.", "summaryKo": "그가 인터뷰한 영웅들은 모두 같은 말을 해요: ''그들도 나를 위해 그렇게 했을 거야.'' 신뢰와 협력은 감정이지 지시가 아니에요. 사람들에게 신뢰하라, 협력하라고 명령할 수 없어요 — 자연스럽게 내면에서 우러나와야 해요.", "keyPoints": ["''They would have done it for me'' — universal answer from heroes", "Trust and cooperation are feelings, not instructions", "You cannot command someone to trust you"], "titleKo": "그가 인터뷰한 영웅들은 모두 같은 말을 해요:…"}, {"section": "The Circle of Safety: 50,000 Years of Evolution", "startSegment": 45, "endSegment": 59, "summary": "Going back 50,000 years, humans evolved as social animals. They formed tribes — ''circles of safety'' — where belonging generated trust and cooperation. Those inside could sleep at night knowing others watched for danger. Without trust, the survival system breaks down.", "summaryKo": "5만 년 전으로 돌아가면, 인간은 사회적 동물로 진화했어요. 부족을 형성했는데, 이것이 ''안전의 원''이에요. 소속감이 신뢰와 협력을 만들어냈어요. 안에 있는 사람들은 다른 사람이 위험을 감시해준다는 걸 알기에 밤에 잠들 수 있었어요. 신뢰 없이는 생존 시스템이 무너져요.", "keyPoints": ["Humans evolved as social animals in a dangerous world", "The ''circle of safety'' concept: tribes where people felt they belonged", "Safety produces trust and cooperation naturally", "Without trust, the survival system fails"], "titleKo": "5만 년 전으로 돌아가면, 인간은 사회적 동물로…"}, {"section": "Modern Organizations Mirror the Paleolithic Era", "startSegment": 60, "endSegment": 75, "summary": "The modern world mirrors the Paleolithic era: external threats like economic uncertainty, new technology, and competition are constants we cannot control. The only variable is conditions inside the organization. When leaders prioritize people''s safety over tangible results, remarkable things happen.", "summaryKo": "현대 세계는 구석기 시대를 반영해요: 경제적 불확실성, 신기술, 경쟁 같은 외부 위협은 우리가 통제할 수 없는 상수예요. 유일한 변수는 조직 내부의 조건이에요. 리더가 가시적 결과보다 사람들의 안전을 우선시하면 놀라운 일이 일어나요.", "keyPoints": ["External threats (economy, technology, competition) are uncontrollable constants", "Internal conditions are the only variable — and that''s where leadership matters", "Leaders set the tone by putting people''s safety first"], "titleKo": "현대 세계는 구석기 시대를 반영해요: 경제적 불…"}, {"section": "Unsafe Leaders Create Unsafe Behavior", "startSegment": 76, "endSegment": 107, "summary": "Sinek shares the story of an airline gate agent who mistreated a passenger — not because she was a bad person, but because she didn''t feel safe from her leaders. He contrasts this with Southwest Airlines, where employees don''t fear leadership. Great leadership is like great parenting: providing opportunity, education, and discipline so people can achieve more than we imagined.", "summaryKo": "사이넥은 승객을 함부로 대한 항공사 직원의 이야기를 들려줘요 — 나쁜 사람이어서가 아니라 리더로부터 안전하다고 느끼지 못했기 때문이에요. 직원들이 리더십을 두려워하지 않는 사우스웨스트 항공과 대비해요. 훌륭한 리더십은 훌륭한 부모됨과 같아요: 기회, 교육, 훈육을 제공해서 사람들이 우리가 상상한 것 이상을 이룰 수 있게 하는 거예요.", "keyPoints": ["Airline gate agent story: she mistreated passengers because she felt unsafe", "Southwest Airlines succeeds because employees don''t fear their leaders", "Unsafe conditions force people to protect themselves from each other", "Great leaders are like great parents — they help people grow"], "titleKo": "사이넥은 승객을 함부로 대한 항공사 직원의 이야…"}, {"section": "Three Cases: NextJump, Banking CEOs, Bob Chapman", "startSegment": 108, "endSegment": 156, "summary": "Three powerful examples: Charlie Kim''s lifetime employment policy at NextJump treats employees like family. Banking CEOs with disproportionate bonuses violated the social contract of leadership by sacrificing people for numbers. Bob Chapman of Barry-Wehmiller chose furloughs over layoffs during the 2008 recession, saying ''better we all suffer a little than any suffer a lot'' — morale rose, they saved $20M, and employees spontaneously traded furlough weeks to help each other.", "summaryKo": "세 가지 강력한 사례: 찰리 킴의 넥스트점프 평생 고용 정책은 직원을 가족처럼 대해요. 불균형적 보너스를 받는 은행 CEO들은 숫자를 위해 사람을 희생시키며 리더십의 사회적 계약을 위반했어요. 배리-웨밀러의 밥 채프먼은 2008년 불경기에 해고 대신 순환 휴직을 선택하며 ''모두가 조금 고통받는 게 낫다''고 했어요 — 사기가 올랐고, 2천만 달러를 절약했으며, 직원들이 자발적으로 휴가를 교환했어요.", "keyPoints": ["NextJump: lifetime employment, coaching instead of firing", "Banking CEOs violated leadership by sacrificing people for personal gain", "Bob Chapman chose furloughs over layoffs — ''all suffer a little''", "Employees spontaneously traded furlough weeks to help each other"], "titleKo": "세 가지 강력한 사례: 찰리 킴의 넥스트점프 평…"}, {"section": "Leadership Is a Choice, Not a Rank", "startSegment": 157, "endSegment": 186, "summary": "Sinek declares that leadership is a choice, not a rank. True leaders are not those with authority, but those who choose to look after the people around them. He closes with a story of a Marine officer who ate last, and his men brought him food — because leaders go first, take risks first, and sacrifice first. When they do, people willingly give their blood, sweat, and tears in return.", "summaryKo": "사이넥은 리더십은 선택이지 직급이 아니라고 선언해요. 진정한 리더는 권한을 가진 사람이 아니라 주변 사람을 돌보기로 선택한 사람이에요. 마지막에 먹은 해병대 장교 이야기로 마무리해요 — 부하들이 음식을 가져다줬어요. 리더가 먼저 가고, 먼저 위험을 감수하고, 먼저 희생하면, 사람들은 기꺼이 피와 땀과 눈물로 보답해요.", "keyPoints": ["Leadership is a choice, not a rank", "Authority is not the same as leadership", "True leaders look after the people around them", "Marine officer ate last — his men brought him their food", "Leaders go first, take risks first, sacrifice first"], "titleKo": "사이넥은 리더십은 선택이지 직급이 아니라고 선언"}], "signalExpressions": [{"expression": "There''s a man by the name of Captain William Swenson", "type": "emphasis", "segmentIndex": 1, "role": "구체적인 인물 이야기로 시작하며 청중의 관심을 끌어요"}, {"expression": "I saw this, and I thought to myself", "type": "transition", "segmentIndex": 19, "role": "이야기에서 화자의 개인적 성찰로 전환해요"}, {"expression": "You know, in the military, they give medals to people", "type": "transition", "segmentIndex": 24, "role": "군대와 비즈니스의 대비를 도입하며 핵심 논점을 제시해요"}, {"expression": "But that''s completely wrong", "type": "emphasis", "segmentIndex": 30, "role": "앞선 가정을 강하게 부정하며 반전을 만들어요"}, {"expression": "Because they would have done it for me", "type": "emphasis", "segmentIndex": 38, "role": "영웅들의 공통된 대답으로 신뢰의 본질을 보여줘요 — 강연의 핵심 메시지"}, {"expression": "If you go back 50,000 years to the Paleolithic era", "type": "transition", "segmentIndex": 45, "role": "시간적 맥락을 크게 전환하며 진화적 근거를 소개해요"}, {"expression": "The modern day is exactly the same thing", "type": "transition", "segmentIndex": 60, "role": "과거 원시시대에서 현대로 연결하며 비유를 완성해요"}, {"expression": "The only variable are the conditions inside the organization", "type": "emphasis", "segmentIndex": 70, "role": "리더십의 역할을 강조하며 핵심 주장을 명확히 해요"}, {"expression": "The closest analogy I can give to what a great leader is", "type": "transition", "segmentIndex": 98, "role": "리더십을 부모됨에 비유하며 새로운 관점을 제시해요"}, {"expression": "This is what so offends us, not the numbers", "type": "emphasis", "segmentIndex": 126, "role": "감정적 반응의 진짜 원인을 짚어주며 청중의 공감을 이끌어요"}, {"expression": "Leadership is a choice. It is not a rank.", "type": "emphasis", "segmentIndex": 157, "role": "결론부의 핵심 명제로, 강연 전체를 하나의 문장으로 압축해요"}, {"expression": "We call them leaders because they go first", "type": "summary", "segmentIndex": 173, "role": "반복 구조로 리더의 정의를 강화하며 감동적으로 마무리해요"}]}'::jsonb WHERE language = 'en' AND video_id = 'lmyZMtPVodo';
UPDATE public.video_artifacts SET structure = '{"sections": [{"section": "Introduction", "startSegment": 0, "endSegment": 4, "summary": "The host introduces the lesson topic: improving English pronunciation using the IPA (International Phonetic Alphabet).", "summaryKo": "진행자가 수업 주제를 소개합니다: IPA(국제 음성 기호)를 사용한 영어 발음 향상.", "keyPoints": ["영어 발음 향상에는 원어민과 IPA라는 도구가 필요하다", "IPA는 국제 음성 기호(International Phonetic Alphabet)의 약자이다"], "titleKo": "진행자가 수업 주제를 소개합니다: IPA(국제…"}, {"section": "The Problem with English Spelling", "startSegment": 5, "endSegment": 17, "summary": "Explains why English is difficult to pronounce by showing that the same letters can represent different sounds, using the letter C as an example (cup, place, chocolate, ache).", "summaryKo": "같은 글자가 다른 소리를 나타낼 수 있음을 보여주며 영어 발음이 어려운 이유를 설명합니다. 글자 C를 예시로 사용합니다 (cup, place, chocolate, ache).", "keyPoints": ["많은 언어에서는 글자와 소리가 1:1로 대응하지만 영어는 그렇지 않다", "같은 글자 C가 단어에 따라 /k/, /s/, /tʃ/ 등 다르게 발음된다", "영어 철자만으로는 정확한 발음을 알 수 없다"], "titleKo": "같은 글자가 다른 소리를 나타낼 수 있음을 보여…"}, {"section": "Why IPA is Useful", "startSegment": 18, "endSegment": 27, "summary": "Demonstrates the value of the IPA by showing how words like ''though'', ''thought'', and ''cough'' have the same spelling (OUGH) but different pronunciations, and how IPA symbols clarify this.", "summaryKo": "''though'', ''thought'', ''cough'' 같은 단어들이 같은 철자(OUGH)를 가지지만 다른 발음을 가짐을 보여주며 IPA의 가치를 설명합니다.", "keyPoints": ["IPA에서는 모든 소리에 고유한 기호가 있다", "IPA를 읽으면 영어 단어를 정확히 어떻게 발음하는지 알 수 있다", "같은 OUGH 철자도 though, thought, cough에서 모두 다르게 발음된다"], "titleKo": "though'', ''thought'', ''cough…"}, {"section": "Getting Started with IPA", "startSegment": 28, "endSegment": 40, "summary": "Encourages viewers not to be intimidated by IPA symbols and explains that English has 44 sounds but only 26 letters, which is why the IPA is necessary.", "summaryKo": "IPA 기호에 겁먹지 말라고 격려하며, 영어에는 26개의 글자밖에 없지만 44개의 소리가 있어서 IPA가 필요하다고 설명합니다.", "keyPoints": ["IPA 기호가 처음에는 무섭게 보일 수 있지만 실제로는 매우 도움이 된다", "영어 알파벳에는 26개의 글자가 있지만 44개의 다른 소리가 있다", "소리가 글자보다 많기 때문에 IPA가 필요하다"], "titleKo": "IPA 기호에 겁먹지 말라고 격려하며, 영어에는…"}, {"section": "Vowel Sounds", "startSegment": 41, "endSegment": 57, "summary": "Covers the English vowel sounds, noting that although there are only 5 vowel letters (A, E, I, O, U), there are many more vowel sounds including long, short, and schwa sounds.", "summaryKo": "영어 모음 소리를 다룹니다. 모음 글자는 5개(A, E, I, O, U)뿐이지만 긴 소리, 짧은 소리, 슈와 소리를 포함하여 훨씬 더 많은 모음 소리가 있음을 설명합니다.", "keyPoints": ["영어 모음 글자는 5개이지만 모음 소리는 훨씬 많다", "모음 소리에는 긴 소리, 짧은 소리, 게으른(슈와) 소리가 있다", "각 모음 소리의 IPA 기호를 배운다"], "titleKo": "영어 모음 소리를 다룸"}, {"section": "Diphthongs", "startSegment": 58, "endSegment": 68, "summary": "Introduces diphthongs — vowel sounds that transition from one sound to another within the same syllable. Demonstrates each diphthong with mouth position changes.", "summaryKo": "이중모음을 소개합니다 — 같은 음절 안에서 한 소리에서 다른 소리로 전환되는 모음 소리입니다. 각 이중모음을 입 모양 변화와 함께 시범합니다.", "keyPoints": ["이중모음은 같은 음절 안에서 한 모음 소리에서 다른 모음 소리로 변하는 소리이다", "이중모음을 발음할 때 입 모양이 변하는 것을 관찰할 수 있다", "이중모음의 이름은 기억할 필요 없고 소리만 기억하면 된다"], "titleKo": "이중모음을 소개합니다 — 같은 음절 안에서 한…"}, {"section": "Consonant Sounds", "startSegment": 69, "endSegment": 76, "summary": "Covers consonant sounds, explaining the difference between voiced and unvoiced (voiceless) consonants. Voiced sounds use vocal cord vibration while unvoiced sounds use only air.", "summaryKo": "자음 소리를 다루며 유성음과 무성음의 차이를 설명합니다. 유성음은 성대 진동을 사용하고 무성음은 공기만 사용합니다.", "keyPoints": ["자음 소리는 공기가 입 뒤쪽에서 입술 밖으로 이동하며 만들어진다", "유성음은 성대를 진동시켜 만들어지고, 무성음은 공기만으로 만들어진다", "목에 손을 대면 유성음과 무성음의 차이를 느낄 수 있다"], "titleKo": "자음 소리를 다루며 유성음과 무성음의 차이를 설…"}, {"section": "Conclusion", "startSegment": 77, "endSegment": 81, "summary": "Wraps up the lesson and directs viewers to download a free worksheet for IPA practice, subscribe to the channel, and watch the next video about vowel sounds.", "summaryKo": "수업을 마무리하고 시청자들에게 IPA 연습용 무료 학습지 다운로드, 채널 구독, 모음 소리에 대한 다음 영상 시청을 안내합니다.", "keyPoints": ["웹사이트에서 무료 IPA 연습 학습지를 다운로드할 수 있다", "채널을 구독하면 다음 수업을 받을 수 있다", "다음 영상은 영어 모음 소리에 대한 내용이다"], "titleKo": "수업을 마무리하고 시청자들에게 IPA 연습용 무…"}], "signalExpressions": [{"expression": "Hey guys!", "type": "hook", "segmentIndex": 0, "role": "시청자의 주의를 끄는 친근한 인사"}, {"expression": "I know you''re super keen to", "type": "hook", "segmentIndex": 0, "role": "시청자의 동기와 욕구에 공감하여 관심을 유도"}, {"expression": "Don''t worry", "type": "transition", "segmentIndex": 4, "role": "시청자의 불안감을 줄이며 설명으로 전환"}, {"expression": "This is why", "type": "transition", "segmentIndex": 18, "role": "앞의 문제점에서 해결책(IPA)으로 연결하는 인과 전환"}, {"expression": "For example", "type": "transition", "segmentIndex": 23, "role": "구체적인 예시를 제시하며 설명을 뒷받침"}, {"expression": "Don''t freak out!", "type": "transition", "segmentIndex": 35, "role": "시청자를 안심시키며 실습 단계로 전환"}, {"expression": "In today''s lesson, we''re going to go through", "type": "transition", "segmentIndex": 35, "role": "수업의 본론으로 들어가는 전환 신호"}, {"expression": "Let''s look at vowels first", "type": "transition", "segmentIndex": 41, "role": "첫 번째 주제(모음)로 전환하는 신호"}, {"expression": "Let''s go through them", "type": "transition", "segmentIndex": 48, "role": "실습 단계로 넘어가는 전환 신호"}, {"expression": "There''s another group of vowel sounds called diphthongs", "type": "transition", "segmentIndex": 58, "role": "새로운 소리 그룹(이중모음)으로 전환"}, {"expression": "Watch my mouth position change", "type": "transition", "segmentIndex": 62, "role": "시각적 시범으로 전환하는 지시 신호"}, {"expression": "Well that''s it for this lesson", "type": "conclusion", "segmentIndex": 77, "role": "수업의 종료를 알리는 마무리 신호"}, {"expression": "Make sure you subscribe", "type": "conclusion", "segmentIndex": 79, "role": "구독을 유도하는 행동 촉구(CTA)"}, {"expression": "See you then!", "type": "conclusion", "segmentIndex": 81, "role": "다음 영상을 기대하게 하는 마무리 인사"}]}'::jsonb WHERE language = 'en' AND video_id = 'n4NVPg2kHv4';
UPDATE public.video_artifacts SET structure = '{"sections": [{"section": "Introduction", "startSegment": 0, "endSegment": 14, "summary": "The speaker introduces the concept of a plank challenge, describing the physical and mental strain involved, and sets up the story of George Hood''s world record for the longest plank. This establishes the topic of mental toughness and physical endurance.", "summaryKo": "말하는 사람은 플랭크 운동의 고통을 묘사하며, 기록을 세운 조지 후드의 이야기를 소개하여 정신적 강함과 신체적 견고함의 주제를 설정합니다.", "keyPoints": ["Plank challenge as a metaphor for mental toughness", "George Hood''s world record of 10 hours", "Introduction of the concept of grit"], "titleKo": "말하는 사람은 플랭크 운동의 고통을 묘사하며,…"}, {"section": "Main Argument (BDNF and Science)", "startSegment": 15, "endSegment": 30, "summary": "The speaker transitions to explaining brain-derived neurotrophic factor (BDNF), a protein linked to mental resilience and memory, and its connection to physical exercise like planking. This section bridges the plank challenge to scientific research.", "summaryKo": "말하는 사람은 정신적 회복력과 기억력에 연결된 뇌 유도 신경성장 인자(BDNF)를 설명하며, 플랭크 운동과의 연결점을 강조합니다.", "keyPoints": ["BDNF as ''fertilizer for the brain''", "Exercise as the most effective way to increase BDNF", "Plank as a potential exercise for mental toughness"], "titleKo": "말하는 사람은 정신적 회복력과 기억력에 연결된…"}, {"section": "Examples and Case Studies", "startSegment": 31, "endSegment": 55, "summary": "The speaker presents real-life examples of individuals (George Hood and Daniel) who demonstrate grit and the role of BDNF in overcoming severe physical and mental challenges, including chronic pain and disability.", "summaryKo": "말하는 사람은 조지 후드와 다니엘과 같은 실제 사례를 통해 정신적 강함과 BDNF가 심각한 신체적/정신적 도전을 극복하는 데 어떻게 기여하는지 보여줍니다.", "keyPoints": ["George Hood''s mental focus during the plank", "Daniel''s CRPS pain and his nine-hour plank", "BDNF''s role in resilience and pain management"], "titleKo": "말하는 사람은 조지 후드와 다니엘과 같은 실제…"}, {"section": "Study Results and Conclusion", "startSegment": 56, "endSegment": 98, "summary": "The speaker discusses recent research on BDNF and exercise, highlights the need for further studies, and concludes with a call to action for the audience to embrace planking as a tool for building grit and improving quality of life.", "summaryKo": "말하는 사람은 BDNF와 운동에 대한 최신 연구를 언급하며, 추가 연구의 필요성을 강조하고, 청중에게 플랭크를 통해 정신적 강함을 키우는 도전을 제안합니다.", "keyPoints": ["2005 study on mental effort vs. physical exercise", "Current study on CRPS and plank therapy", "Call to action: ''Do a plank when you need grit''"], "titleKo": "말하는 사람은 BDNF와 운동에 대한 최신 연구…"}], "signalExpressions": [{"expression": "You''re about to hold a plank. Just 60 seconds.", "type": "hook", "segmentIndex": 1, "role": "청중의 주의를 끌며 운동의 시작을 알리는 개요 제공"}, {"expression": "But there was something deeper happening here.", "type": "transition", "segmentIndex": 30, "role": "주제 전환: 플랭크의 물리적 고통에서 정신적 과정으로 이동"}, {"expression": "What makes the concept of grit and BDNF so compelling to me", "type": "transition", "segmentIndex": 56, "role": "새로운 주제로 전환: 실생활 사례와 연구 결과 소개"}, {"expression": "I''m here to raise awareness so that this relationship between exercise, BDNF, and improving the quality of life may be studied further.", "type": "conclusion", "segmentIndex": 90, "role": "결론: 연구의 필요성 강조 및 메시지 요약"}, {"expression": "Now, I''m going to leave you with the challenge.", "type": "conclusion", "segmentIndex": 95, "role": "청중에게 행동을 유도하는 마무리 메시지"}, {"expression": "Now, think about that for a minute.", "type": "emphasis", "segmentIndex": 54, "role": "청중의 사고를 유도하며 주제를 강조"}]}'::jsonb WHERE language = 'en' AND video_id = 'rNxC16mlO60';
UPDATE public.video_artifacts SET structure = '{"sections": [{"section": "Nothing Is Worthwhile Unless You Take Risks", "startSegment": 0, "endSegment": 6, "summary": "Denzel opens with Nelson Mandela''s quote about the danger of playing small. He rejects the idea of having something to ''fall back on'' and introduces his central metaphor: fall forward.", "summaryKo": "덴젤은 작게 행동하는 것의 위험성에 대한 넬슨 만델라의 명언으로 시작해요. ''뒤로 물러설 곳''을 마련하라는 생각을 거부하고, 핵심 비유인 ''앞으로 넘어지라''를 소개해요.", "keyPoints": ["Nothing in life is worthwhile unless you take risks", "Rejects the concept of ''falling back on'' something safe", "Introduces the key metaphor: fall forward"], "titleKo": "덴젤은 작게 행동하는 것의 위험성에 대한 넬슨…"}, {"section": "Take Risks: Reggie Jackson and Thomas Edison", "startSegment": 7, "endSegment": 15, "summary": "Denzel encourages the audience to be consistent, take chances, and think outside the box. He uses examples of Reggie Jackson''s strikeouts and Thomas Edison''s failed experiments to show that failure leads to success.", "summaryKo": "덴젤은 청중에게 꾸준하고 기회를 잡으며 틀 밖에서 생각하라고 격려해요. 레지 잭슨의 삼진과 토마스 에디슨의 실패한 실험을 예로 들어 실패가 성공으로 이어진다는 것을 보여줘요.", "keyPoints": ["Consistency is essential to finishing what you start", "Think outside the box and dream big", "Reggie Jackson''s 2,600 strikeouts vs. remembered home runs", "Edison''s 1,000 failed experiments led to the light bulb"], "titleKo": "덴젤은 청중에게 꾸준하고 기회를 잡으며 틀 밖에…"}, {"section": "Personal Failure: The Broadway Audition", "startSegment": 16, "endSegment": 28, "summary": "Denzel shares his personal story of failing a Broadway audition because he couldn''t sing, but persevering through repeated failures. Years later, he performed at the same theater where he first failed, proving the value of persistence.", "summaryKo": "덴젤은 노래를 못해서 브로드웨이 오디션에 떨어진 개인적인 이야기를 나눠요. 반복된 실패에도 포기하지 않았고, 수년 후 처음 떨어졌던 바로 그 극장에서 공연하며 끈기의 가치를 증명해요.", "keyPoints": ["Failure is inevitable — accept and embrace it", "Failed a Broadway audition because he couldn''t sing", "Kept preparing for the next audition without quitting", "Performed ''Fences'' at the same theater 30 years later"], "titleKo": "덴젤은 노래를 못해서 브로드웨이 오디션에 떨어진…"}, {"section": "Ghosts of Unfulfilled Potential", "startSegment": 29, "endSegment": 36, "summary": "Denzel presents the powerful metaphor of ghosts on your deathbed — the unfulfilled ideas, talents, and potential that die with you if you don''t act. He challenges the audience to minimize their ''ghosts.''", "summaryKo": "덴젤은 임종의 침대 위 유령이라는 강력한 비유를 제시해요. 행동하지 않으면 함께 죽는 이루지 못한 아이디어, 재능, 잠재력을 나타내는 유령들이에요. 청중에게 ''유령''을 줄이라고 도전해요.", "keyPoints": ["To get what you never had, do what you never did", "Ghosts of unfulfilled potential surround your deathbed", "These ghosts are angry because you could have brought them to life", "Challenge: How many ghosts will be at your bed?"], "titleKo": "덴젤은 임종의 침대 위 유령이라는 강력한 비유를…"}, {"section": "The World Needs Your Help", "startSegment": 37, "endSegment": 50, "summary": "Denzel calls the graduates to action, pointing out that the world desperately needs their help — from Africa to Alabama. He asks them to give everything they have, whether it''s time, talent, patience, or love.", "summaryKo": "덴젤은 졸업생들에게 행동을 촉구하며, 아프리카에서 앨라배마까지 세상이 절실히 도움을 필요로 한다고 말해요. 시간이든 재능이든 인내든 사랑이든 가진 모든 것을 쏟으라고 요청해요.", "keyPoints": ["The world has terrible poverty and needs your help", "Give everything: time, talent, prayers, treasures", "It''s not about how much you have, but what you do with it", "Repeated rhetorical question: What are you going to do with what you have?"], "titleKo": "덴젤은 졸업생들에게 행동을 촉구하며, 아프리카에…"}, {"section": "A Winding Path: From Failed Pre-Med to Actor", "startSegment": 51, "endSegment": 68, "summary": "Denzel shares his own winding path from failed pre-med student to actor. At his lowest point, an elderly woman in his mother''s beauty shop prophesied he would speak to millions — which came true through his movie career.", "summaryKo": "덴젤은 실패한 의대 예과생에서 배우가 된 자신의 구불구불한 인생 경로를 나눠요. 가장 낮은 지점에서 어머니의 미용실에서 한 노부인이 수백만 명에게 말하게 될 거라고 예언했고, 영화 경력을 통해 실현됐어요.", "keyPoints": ["Life is never a straight path", "Failed pre-med, pre-law, and journalism before finding acting", "Had a 1.8 GPA and was asked to take time off from university", "An elderly woman prophesied he would speak to millions"], "titleKo": "덴젤은 실패한 의대 예과생에서 배우가 된 자신의…"}, {"section": "Never Be Discouraged, Fall Forward", "startSegment": 69, "endSegment": 78, "summary": "Denzel closes by expressing gratitude and encouragement to the graduates. He urges them to hold onto faith, never be discouraged, give everything they have, and always remember to fall forward.", "summaryKo": "덴젤은 졸업생들에게 감사와 격려를 표현하며 마무리해요. 믿음을 붙잡고 절대 낙심하지 말며, 가진 모든 것을 주고, 항상 앞으로 넘어지라는 것을 기억하라고 촉구해요.", "keyPoints": ["Encouraged and strengthened by what he sees in the graduates", "Faith will define you", "Never be discouraged, never hold back", "Final message: Fall forward"], "titleKo": "덴젤은 졸업생들에게 감사와 격려를 표현하며 마무…"}], "signalExpressions": [{"expression": "I found that nothing in life is worthwhile unless you take risks", "type": "emphasis", "segmentIndex": 0, "role": "강렬한 첫 문장으로 청중의 주의를 끌고 연설의 핵심 주제를 바로 제시해요"}, {"expression": "I want to fall forward", "type": "emphasis", "segmentIndex": 6, "role": "연설의 핵심 비유를 소개하며 전체 메시지의 중심축을 설정해요"}, {"expression": "Don''t be afraid to fail big, to dream big", "type": "emphasis", "segmentIndex": 10, "role": "반복적인 명령문으로 청중에게 두려움을 극복하라고 직접적으로 격려해요"}, {"expression": "Fall forward", "type": "transition", "segmentIndex": 13, "role": "핵심 구절을 반복하며 예시들 사이의 전환 역할을 해요"}, {"expression": "You will fail at some point in your life. Accept it.", "type": "emphasis", "segmentIndex": 17, "role": "실패의 불가피성을 단정적으로 선언하며 새로운 논점으로 전환해요"}, {"expression": "But here''s the thing", "type": "transition", "segmentIndex": 22, "role": "중요한 반전 포인트를 알리며 실패 후 포기하지 않은 이야기로 전환해요"}, {"expression": "To get something you never had, you have to do something you never did", "type": "emphasis", "segmentIndex": 30, "role": "대구법으로 기억에 남는 교훈을 전달하며 유령 비유의 도입부 역할을 해요"}, {"expression": "So I ask you today", "type": "summary", "segmentIndex": 36, "role": "유령 비유를 마무리하며 청중에게 직접적인 질문으로 성찰을 촉구해요"}, {"expression": "The world needs a lot and we need it from you", "type": "transition", "segmentIndex": 41, "role": "개인적 이야기에서 사회적 책임으로 주제를 전환해요"}, {"expression": "What are you going to do with what you have?", "type": "emphasis", "segmentIndex": 46, "role": "반복되는 수사적 질문으로 청중의 능동적 참여와 자기 성찰을 유도해요"}, {"expression": "Your life will never be a straight path", "type": "transition", "segmentIndex": 53, "role": "개인적 경험담으로 전환하며 실패가 인생의 자연스러운 부분임을 보여줘요"}, {"expression": "Never be discouraged, never hold back", "type": "summary", "segmentIndex": 75, "role": "전체 연설의 메시지를 압축하며 마지막 당부로 마무리해요"}]}'::jsonb WHERE language = 'en' AND video_id = 'tbnzAVRZ9Xc';
COMMIT;
